/* carfdeep4.js - field-by-field walkthroughs (split 4: addenda/amendments, brokerage admin & compensation,
   LPT Realty brokerage forms, short sale/REO/probate/trust). Merged into CARF_DEEP by app64.js.
   LPT Realty internal forms are described from SkySlope titles/usage only (no public source) - confirm with LPT broker/TC.
   Not legal advice. Written 2026-10-26. */
window.CARF_DEEP_EXT=Object.assign(window.CARF_DEEP_EXT||{},{
"ACS":[
{s:"Header: property / transaction identification",d:"Enter the property address (or client name and search area if no property yet) and the date. If tied to a listing, cite the RLA date; if tied to an offer, the RPA date. Common mistake: leaving this generic so the split cannot be matched to a specific commission check later. LPT ties the ACS to the Commission Intake Form, so the address must match SkySlope exactly."},
{s:"Agents and brokers (parties)",d:"Name each participating agent, their DRE license number and the responsible broker/brokerage for each. If both agents are LPT, list LPT Realty once with both agents under it. If one agent is at another brokerage, the split becomes broker-to-broker and the other broker must sign. Never list a team name as a party; teams are not licensees."},
{s:"Compensation split",d:"State the split as a percentage of the gross compensation the broker actually receives, or a flat dollar amount, and say which side (listing/buyer) it applies to. Specify whether the split is before or after brokerage fees/caps (verify on the current form). Mistake: writing a percentage of the sale price instead of a share of the commission."},
{s:"Services each agent provides",d:"Describe who does what: showings, negotiation, disclosures, escrow follow-up, open houses. This matters if the deal fails or one agent stops performing; it also documents that both are performing licensed services, which supports paying each (compensation cannot go to someone who did nothing licensed)."},
{s:"Costs, referrals and failed transactions",d:"Allocate shared costs (staging, photos, marketing) and state whether an outgoing referral fee comes off the top before the split. Say what happens if escrow cancels: usually no compensation, costs borne per the agreement. If a different agent is the procuring cause of a later sale, say whether the split still applies."},
{s:"Broker approval and signatures",d:"All agents sign and date; each responsible broker (or LPT designated broker/manager) signs to approve. Compensation is paid through brokers only, never agent to agent, so an ACS without broker signatures is not payable. Confirm LPT's approval workflow with the LPT broker/TC."},
{s:"Filing and payout",d:"Upload to SkySlope and attach to the LPT Commission Intake Form (split check version if two agents are paid). Escrow pays LPT, and LPT disburses per the ACS; the CDA must mirror these numbers or the check will be held. Loan implication: none directly, but any client credit funded from this split must still appear on the CD."}
],
"ADM-GEN":[
{s:"Reference block: agreement being supplemented",d:"Check the box or write the name of the underlying agreement (e.g., California Residential Purchase Agreement, Residential Listing Agreement, BRBC, lease), its date, the property address and the exact names of the parties as they appear on that agreement. A mismatched date or missing buyer name is the most common reason an addendum is challenged later."},
{s:"Numbered terms (body)",d:"Write each added term as a separate numbered paragraph with specific dollar amounts, item descriptions and deadlines stated as calendar dates or days after acceptance. Say who performs and who pays. Avoid vague promises like seller to fix roof; instead: Seller to have licensed roofer repair the leak over the garage, with receipt delivered to buyer 5 days before COE."},
{s:"Conflict / precedence language",d:"If a term changes a paragraph of the main agreement, say so explicitly: This addendum supersedes paragraph X of the RPA to the extent of any conflict. Without this, both provisions may be read together and create ambiguity. Do not use ADM to change price, COE or contingencies after acceptance when AEA, ETA or CR-B exists."},
{s:"Incorporation into an offer",d:"If the ADM is part of the offer, list it in the RPA addenda/other terms checklist (RPA paragraph 3 area, verify on the current form) so it is incorporated. An unlisted addendum may not be part of the contract. Counter offers that accept the offer also accept listed addenda unless they say otherwise."},
{s:"Signatures and delivery",d:"Every party to the underlying agreement signs and dates (all buyers, all sellers, or client and broker for listing/BRBC changes). A post-acceptance ADM becomes binding only when signed by all and delivered. Deliver to the other agent and escrow the same day and upload to SkySlope."},
{s:"Loan and escrow implications",d:"Any term that changes price, credits, occupancy, personal property with value, repairs or COE must go to the MLO immediately so the loan file, appraisal and Closing Disclosure match the contract. Credits written on an ADM count toward interested-party contribution limits (VA 4% concessions, FHA/conventional IPC caps)."},
{s:"Multiple copies in SkySlope",d:"Three generic copies (ADM-GEN, ADM-GEN-1, ADM-GEN-3) exist so a file can hold several addenda. Number them sequentially (Addendum No. 1, 2, 3) and reference the previous ones if a later addendum modifies an earlier one. Keep the numbering consistent with escrow's file."}
],
"LPT-ABAD":[
{s:"Version selection",d:"SkySlope holds six versions: general Notice, Buyers, Sellers, Landlords, Tenants and LPT Network Realty. Use the one matching the client role and brokerage entity named on the representation agreement. If the client is both (e.g., selling and buying), deliver both. (confirm with LPT broker/TC which version is required for California files)"},
{s:"Client and property",d:"Enter the client legal name(s) and the property address or, for buyers/tenants with no property yet, the search area or N/A. Date the disclosure on the day it is delivered, which must be at or before the referral to the affiliated provider."},
{s:"Affiliated provider and relationship",d:"The form should pre-print the affiliated settlement service provider(s) (e.g., title, escrow, mortgage, home warranty) and LPT's ownership/financial interest as supplied by LPT. Do not edit these blocks yourself; if the provider or percentage looks outdated, stop and ask the LPT broker/TC. RESPA requires the nature of the relationship to be stated accurately."},
{s:"Estimated charges",d:"The range or estimate of the provider's charges must be shown as LPT supplies them. Leave this as pre-printed; agents should not insert their own estimates. If a buyer asks about actual costs, refer them to the provider's quote and the Loan Estimate."},
{s:"Not-required-to-use statement",d:"The disclosure must state the client is NOT required to use the affiliated provider and may shop for other providers (limited exception: a lender may require a particular attorney, credit bureau or appraiser). Never condition your services, a discount or a credit on using the affiliate."},
{s:"Client acknowledgment and signature",d:"Client signs and dates to acknowledge receipt (acknowledgment of receipt is not consent to use). Each client on the agreement signs. Keep proof of delivery date. Upload to SkySlope before or at the time of the referral; late delivery is a RESPA compliance problem for the brokerage."},
{s:"Loan file implication",d:"If the referral is to an affiliated lender, the lender typically needs the signed AfBA in the loan file as part of its own RESPA compliance; send it to the MLO with the BRBC/RLA. Confirm with the LPT broker/TC whether the Dark Horse ABA form is also required for that provider."}
],
"AOAA":[
{s:"Reference block",d:"Enter the purchase agreement date, property address and the original buyer(s) and seller(s) exactly as on the RPA. Note the RPA paragraph that restricts assignment (RPA generally requires seller written consent to assign; verify on the current form) so the seller consent section below ties to it."},
{s:"Assignor and assignee",d:"Name the assignor (original buyer) and the assignee with its full legal name and entity type (e.g., XYZ Holdings LLC, a California limited liability company) and the person signing for it with their title. Mistake: naming a trust without the trustee or an LLC that is not yet formed; escrow and title will reject it."},
{s:"Assumption of obligations and release",d:"Check whether the assignee assumes all buyer obligations and whether the assignor remains liable (jointly) or is released. Sellers usually want the assignor to stay liable; assignees want a release. Deposit, contingency removals already made and timelines all carry over, so the assignee is bound by prior removals."},
{s:"Assignment fee / consideration",d:"If any consideration is paid for the assignment, disclose it here (verify on the current form). Undisclosed assignment fees in a financed deal can be viewed as a hidden price change; escrow and the lender need to see it. For wholesaling-type assignments, your broker may require additional disclosures."},
{s:"Seller consent",d:"Seller signs the consent section if the RPA requires consent. Without seller consent, the assignment may be ineffective and the seller may treat it as a breach. Agents should not assume consent because the seller was told verbally."},
{s:"Signatures and delivery",d:"Assignor, assignee (and seller if consenting) sign and date. Deliver to escrow so vesting, the escrow instructions and the deed reflect the assignee, and to the lender. Upload to SkySlope and attach an RCSD if the assignee signs in a representative capacity."},
{s:"Loan implication",d:"Most residential lenders will not lend to an LLC or an unapproved borrower; an assignment usually means a brand-new loan application, new disclosures and a new appraisal borrower. Coordinate with the MLO BEFORE the assignment is signed, and recheck the loan contingency date because it does not reset."}
],
"ARB":[
{s:"Reference and parties",d:"Identify the underlying agreement (RPA, listing, BRBC, lease), its date, the property and all parties. The ARB is used only when that agreement has no arbitration clause or the parties did not initial it at signing and now want binding arbitration."},
{s:"Scope of disputes covered",d:"Review the scope language: disputes between the parties arising from the agreement or the transaction, after any required mediation. Check whether brokers are included (brokers may elect to participate; verify on the current form). Agents should explain only what the form says and refer legal questions to an attorney."},
{s:"Exclusions",d:"The form carves out matters such as judicial or non-judicial foreclosure, unlawful detainer, mechanics liens, probate/small-claims matters and provisional remedies (verify on the current form). Explain that these are not arbitrated even if the ARB is signed."},
{s:"Statutory jury-waiver notice",d:"The capitalized notice (CCP 1298) states the parties give up the right to a court/jury trial and to discovery and appeal except as provided in California arbitration law, and that refusing to arbitrate after agreeing may compel arbitration. Do not paraphrase or minimize it; read it as written."},
{s:"Initials and signatures",d:"Each party initials the arbitration provision and signs/dates only if they voluntarily agree. Never pre-fill, pressure, or suggest a client should sign. One party initialing without the other means no agreement to arbitrate. If parties exceed the lines, use LDAA/ASA."},
{s:"Delivery and filing",d:"Deliver signed copies to all parties and upload to SkySlope. There is no escrow or lender action; this is a dispute-resolution election. Recommend clients consult an attorney before signing; C.A.R. forms recommend the same."}
],
"ASA":[
{s:"Reference block",d:"Enter the name/title of the agreement (RPA, counter offer, RLA, BRBC, lease), its date and the property address so the additional signatures cannot be attached to the wrong document. If attached to a counter offer, cite the counter number as well."},
{s:"Additional party names",d:"Type each additional party's full legal name exactly as it will appear on title, the loan application (1003) or the lease. Mistake: using nicknames or omitting a middle initial that appears on vesting. For trusts, name the trustee and trust; for entities, the entity and signer title."},
{s:"Role and capacity",d:"Mark each signer as Buyer, Seller, Landlord or Tenant. If signing in a representative capacity (trustee, attorney-in-fact, officer), attach an RCSD and confirm authority documents go to escrow/title. Each role box should match the role on the main agreement."},
{s:"Binding effect language",d:"The ASA states the additional signers agree to all terms of the referenced agreement. Note that liquidated damages and arbitration still require separate initials from EVERY buyer and seller; the ASA alone does not supply them, so pair with LDAA when the main agreement's initial boxes are full."},
{s:"Routing and signatures",d:"Attach the ASA to the agreement before sending for e-signature so every party signs the same package, with the same date. Each additional party signs and dates and initials any main-agreement pages that require initials. Missing a co-owner's signature can make a listing or contract unenforceable."},
{s:"Filing and escrow",d:"Store with the main agreement in SkySlope and send to escrow so all vesting parties are in the escrow file. Four copies (ASA-1 to ASA-4) exist for multiple agreements in one file; label which agreement each belongs to."},
{s:"Loan implication",d:"Every borrower and non-borrowing spouse on title must be identified to the lender. Names on the ASA should match the 1003 and the vesting on the preliminary title report; a buyer added by ASA who is not on the loan may need lender approval or must sign as a non-borrowing title holder."}
],
"LPT-TRANSFER":[
{s:"Version selection",d:"Two LPT versions: (1) Listing Agreement Not Under Contract and (2) Representation under Purchase Contract. Use (1) for an active/pending-no-escrow listing moving with the agent; use (2) for a buyer or seller representation where a purchase contract is already in place. (confirm with LPT broker/TC)"},
{s:"Client and property",d:"Enter the client legal name(s), property address and the original agreement being transferred (RLA or BRBC date, or RPA date and escrow number for in-contract files). Match the names on the original agreement; the releasing broker will compare."},
{s:"Releasing and receiving brokers",d:"Identify the releasing brokerage and the receiving brokerage (LPT Realty or the other broker, depending on direction), each with the responsible broker name and DRE license number. Listings belong to the broker, so both brokers must consent; the agent cannot move a listing unilaterally."},
{s:"Compensation and obligations",d:"Note how compensation already earned or pending is handled (e.g., referral to the releasing broker, or full transfer) per the brokers' agreement. For in-escrow files, confirm who is named on the commission demand/CDA after transfer. (confirm with LPT broker/TC)"},
{s:"Client authorization and signatures",d:"Client signs authorizing the transfer and release; releasing broker signs the release; receiving broker signs acceptance. All three signatures are needed before anything changes in the MLS or escrow."},
{s:"MLS and escrow updates",d:"After full execution, update the MLS listing brokerage per CRMLS rules (the releasing broker may need to withdraw and the receiving broker re-enter), notify escrow of the new broker/agent contacts and send a revised commission instruction. Upload everything to SkySlope."},
{s:"Loan implication",d:"Mid-escrow representation changes mean the lender and escrow need updated agent/broker contacts, and the buyer-broker compensation shown on the CD must name the new brokerage. Tell the MLO promptly."}
],
"BCA":[
{s:"Purpose and timing",d:"The Broker Compensation Advisory (C.A.R., issued with the July/Aug 2024 NAR-settlement form changes) explains that compensation is not set by law and is negotiable. Give it at the listing appointment and at the buyer consultation BEFORE the RLA or BRBC is signed, and keep it with that agreement."},
{s:"Client and property / search area",d:"Enter the client name(s) and either the property address (sellers) or the search area/N/A (buyers). Date it on delivery. If delivered to a couple, both sign."},
{s:"Negotiability of compensation",d:"Review the section stating there is no standard, customary or legally required rate and that the client may negotiate amount, type (percent, flat, hourly) and who pays. Do not say anything in the meeting that contradicts this (e.g., the normal rate is X)."},
{s:"Seller-side scenarios",d:"Walk through: seller pays listing broker only; seller agrees in the RLA to authorize/pay an amount to the buyer's broker (shown in the RLA compensation paragraph, not in the MLS); seller gives a concession the buyer may use for broker fees. Explain that any buyer-broker payment must be in writing (SPBB, CA, RPA term)."},
{s:"Buyer-side scenarios",d:"Walk through: buyer pays the BRBC amount; seller pays all or part via the RPA/SPBB; the remainder is owed by buyer. Note the BRBC caps what the broker can receive at the agreed amount and that MLS listings cannot carry a compensation offer. Pair with ECC-B for the dollar math."},
{s:"Acknowledgment and signatures",d:"Client initials/acknowledges each section if the form has initial boxes (verify on the current form) and signs and dates. Agent signs. Attach to the RLA or BRBC in SkySlope; LPT compliance checks for it."},
{s:"Loan implication",d:"Seller payment of the buyer's broker is generally NOT counted as a seller concession by VA, FHA, Fannie/Freddie under current guidance, but a seller credit used for closing costs IS. Confirm treatment with the MLO before writing credits, and for VA ensure the veteran is not charged fees VA prohibits."}
],
"BEO":[
{s:"Reference block",d:"Enter the RPA date, property address, buyer and seller names. The BEO is an addendum to the RPA; if written with the offer, list it in the RPA addenda checklist; if agreed later, all parties sign as an amendment."},
{s:"Occupancy start and purpose",d:"Enter the date and time occupancy begins and whether it is full occupancy or limited (e.g., storage plus access). For storage-only use POSA instead. Occupancy before COE creates a landlord-tenant style relationship; be precise about what the buyer may do."},
{s:"Rent / daily charge and deposit",d:"State the per-day amount (or lump sum) and how it is paid (through escrow or directly to seller) plus any additional security deposit held by seller or escrow. Mistake: leaving the charge at zero when the loan program requires rent to be shown; ask the MLO."},
{s:"Utilities, maintenance and condition",d:"Allocate utilities (buyer usually from occupancy date), maintenance and repairs during occupancy, and who bears damage. Record a condition walk-through at move-in. Specify whether the buyer may alter the property (usually not before COE)."},
{s:"Insurance",d:"Require the buyer to carry renter's/liability coverage and the seller to confirm their homeowner's policy allows a non-owner occupant; both should notify insurers in writing. Enter the coverage amounts if the form has blanks (verify on the current form)."},
{s:"If escrow does not close",d:"State the date the buyer must vacate if escrow cancels, holdover charges and whether the deposit is applied to damages. Make vacate terms clear; otherwise the seller may face an unlawful detainer process to remove a buyer who moved in early."},
{s:"Signatures and delivery",d:"Buyer and seller sign; deliver to escrow (rent and deposit may need to be shown on the settlement statement) and upload to SkySlope. Advise both to consult insurance agents and, if unsure, an attorney."},
{s:"Loan implication",d:"Tell the lender before the buyer moves in. Some programs restrict pre-close occupancy, rent paid may need to appear on the CD, and the appraisal/final inspection may be affected by buyer belongings. Early occupancy can also shift the risk-of-loss date on the RPA."}
],
"LPT-BLACKFRIDAYMAR":[
{s:"Agent identification",d:"Enter your name as licensed, LPT agent ID, email on file with LPT, phone and your office/state. This is an agent business form, not a client transaction document, so it belongs in your agent file, not a client SkySlope transaction. (confirm with LPT broker/TC)"},
{s:"Promotion / package selection",d:"Select the marketing package(s) or options offered in the current Black Friday special, per LPT's published promotion terms for that year. Terms, prices and inclusions change annually; do not rely on last year's flyer."},
{s:"Pricing, billing and deadlines",d:"Review the price, how it is billed (card on file, deduction from a closing, invoice) and the enrollment deadline and any refund/cancellation rule stated by LPT. Note the fulfillment timeline so you can plan listings or campaigns around it. (confirm with LPT broker/TC)"},
{s:"Election and signature",d:"Check the opt-in election, sign and date electronically. Submit through SkySlope or the channel LPT names for that promotion."},
{s:"Confirmation and recordkeeping",d:"Keep a copy and confirm enrollment with LPT support; retain the charge receipt for tax records (marketing expense). No loan or escrow implications."}
],
"LPT-CIF":[
{s:"Version selection",d:"Choose the variant matching the payout: Standard (one agent, one check to LPT), Single Check, Split Check (two versions, for two LPT agents or an ACS split), Outgoing Referral (fee leaving to another broker), VA (VA-financed buyer side) or BPO (broker price opinion fee). Using the wrong version is the top cause of held commissions. (confirm with LPT broker/TC)"},
{s:"Property, client and transaction data",d:"Enter the property address exactly as in SkySlope, client name(s), side represented, sale price, acceptance date and expected COE. Mismatches between the CIF and the SkySlope file name delay LPT's commission demand."},
{s:"Escrow / title contacts",d:"Enter escrow company, officer, phone, email and escrow number; title company if separate. LPT sends the commission demand/CDA to this contact, so a wrong email means the demand never arrives."},
{s:"Gross commission and source agreement",d:"Enter the gross compensation due to LPT in percent and dollars and cite the source: RLA paragraph, BRBC amount, SPBB/CA or RPA term. For buyer side, show how much comes from seller vs. buyer. The number must match the CDA and the settlement statement."},
{s:"Referral fees, splits and credits",d:"List outgoing referral fees (payee broker, percent, attach the referral agreement), co-agent/team splits (attach ACS or team agreement) and any approved agent credit to the client (attach the Broker Credit Letter). Credits must already be in the contract or an amendment."},
{s:"Attachments",d:"Attach the executed purchase contract and all addenda, the compensation agreement (RLA/BRBC/SPBB/CA), referral/ACS documents and the Broker Credit Letter if any. For BPO, attach the BPO order/engagement. (confirm with LPT broker/TC)"},
{s:"Submission and timing",d:"Submit via SkySlope for LPT broker/transaction desk approval as soon as the file is in escrow so the demand reaches escrow before the settlement statement is prepared. Late submission is the usual reason commission checks are delayed."},
{s:"Loan implication",d:"For VA files, the veteran may pay reasonable buyer-broker fees only as VA currently permits (confirm with the MLO); credits to the buyer must appear on the CD and fit VA 4% concession/FHA/conventional IPC rules. Any change here requires a Commission Modification Letter and revised CDA."}
],
"LPT-BCL":[
{s:"Version selection",d:"Five versions: Listing Side, Selling Side, Landlords, Tenants and the generic Network Credit Letter. Pick the one matching your client role and the brokerage entity on the agreement. (confirm with LPT broker/TC)"},
{s:"Property, client and escrow",d:"Enter property address, client legal name(s), escrow company and escrow number. For leases, enter the lease date and property management/landlord contact instead of escrow."},
{s:"Credit amount and funding",d:"State the credit in dollars (and the percent of commission if LPT's template shows it). The credit comes out of LPT's compensation, never from the agent's personal funds, so the gross commission on the CIF/CDA must be large enough to cover it."},
{s:"Application of the credit",d:"Say how escrow applies it: toward buyer's recurring/non-recurring closing costs, toward seller's costs, or as a reduction of the net the client pays. Price reductions are NOT done by credit letter; those require an RPA amendment. Tenant credits are usually applied to first month's rent or move-in costs."},
{s:"Contract consistency",d:"The credit should be reflected in the RPA, an ADM or AEA, or the lease so all parties and the lender see it. A credit that appears only in a letter to escrow is a disclosure problem."},
{s:"Broker approval and signatures",d:"Agent prepares; client acknowledges; LPT broker/transaction desk approves and signs. Deliver to escrow and the lender; upload to SkySlope and attach to the CIF/CDA."},
{s:"Loan implication",d:"The lender must approve the credit and show it on the Closing Disclosure (usually on the buyer side as a real estate agent credit). It counts toward interested-party contribution limits (VA 4% for concessions, FHA 6%, conventional 3/6/9% by LTV) and on most loans cannot exceed the buyer's actual closing costs; excess is lost unless reallocated."}
],
"LPT-BUYERPRECLOSIN":[
{s:"Header",d:"Enter property address, walkthrough date/time, and attendees (buyer(s), buyer's agent, anyone else present). Tie it to the RPA date. The RPA gives the buyer the right to a final verification of condition within the last 5 days before COE (verify on the current RPA), so schedule accordingly. (confirm with LPT broker/TC)"},
{s:"Agreed repairs",d:"List each repair the seller agreed to (from the RR/RRRR, counter or addendum) and mark complete/incomplete, with receipts or invoices collected. Note any repair done without the agreed licensed contractor or permit."},
{s:"Systems and appliances check",d:"Run and note: HVAC heat/cool, water heater, plumbing (run faucets, flush toilets), electrical (lights, outlets, GFCI), appliances that convey, garage door openers, smoke/CO detectors and water heater strapping (statutory items)."},
{s:"Included items and personal property",d:"Verify every item in the RPA items-included section and any Personal Property Sheet is present (ranges, refrigerators, washer/dryer, window coverings, remotes, keys, mailbox keys, HOA fobs). Note anything missing or swapped."},
{s:"Condition since acceptance",d:"Note new damage, debris, seller belongings not removed, or landscaping decline. The property must be maintained in substantially the same condition as at acceptance (RPA). Photograph issues."},
{s:"Buyer signature and follow-up",d:"Buyer signs; agent signs. Upload to SkySlope and immediately notify the listing agent in writing of any issues so they can be cured or resolved through escrow (holdback) before funding. Use alongside or instead of C.A.R. VP per LPT instruction."},
{s:"Loan implication",d:"If the appraiser required repairs (FHA/VA MPRs, conventional subject-to), the lender needs a completion report (Form 1004D/442) before funding; a walkthrough form does not replace it. Report any newly discovered damage to the MLO, as it can affect the appraisal."}
],
"CCA":[
{s:"Reference block",d:"Enter the RPA date, property address, buyer name(s), the estate or conservatorship name (Estate of ___) and the superior court case number. The seller is the personal representative/conservator; confirm their exact capacity from the Letters."},
{s:"Court confirmation required",d:"State that the sale is subject to court confirmation (limited IAEA authority or conservatorship). Enter the hearing date if set, or note it will be set after the Report of Sale/Petition is filed. Contract timelines generally run from confirmation, not acceptance (verify on the current form)."},
{s:"Overbid procedure",d:"Explain the minimum first overbid: the accepted price plus 10% of the first $10,000 plus 5% of the excess (Probate Code 10311), and that bidding continues in open court. The original buyer may be outbid and should attend ready to bid."},
{s:"Deposit and refund",d:"Note the deposit amount (commonly 10% of the price; overbidders must bring a cashier's check for 10% of their bid) and whether the original buyer's deposit is refunded if outbid. State where the deposit is held (escrow)."},
{s:"As-is and contingencies",d:"Court-confirmed sales are typically as-is with inspection contingencies run BEFORE the hearing or waived; the court will not confirm a contingent sale in most counties. Set the contingency periods so they expire before the hearing (verify on the current form)."},
{s:"Broker compensation",d:"Compensation is set/approved by the court; if an overbidder wins, the split between listing and overbidder's broker is set by court rule. State the agreed compensation subject to court approval. Pair with PLA on the listing side."},
{s:"Signatures and delivery",d:"Buyer and the personal representative/conservator sign (RCSD attached). Deliver with the RPA to escrow and the estate's attorney. Upload to SkySlope."},
{s:"Loan implication",d:"The lender needs the Order Confirming Sale before docs; rate locks must allow for an uncertain hearing date (often 30-60 days out). Advise financed buyers that the closing date floats with the court calendar."}
],
"CFC":[
{s:"Consumer identification",d:"Enter the consumer's full name, every phone number consent covers (mark mobile vs. landline) and email addresses. Consent attaches to the specific numbers listed; a new number needs a new consent."},
{s:"Communication methods",d:"Check each method consented to: calls, text/SMS, email, pre-recorded/artificial voice, autodialed calls. TCPA treats autodialed/pre-recorded calls and texts to cell phones as requiring prior express written consent, so be specific."},
{s:"Purposes",d:"Check the purposes: this transaction, future listings/market updates, marketing of services. Keep purposes aligned with how your CRM campaigns are set up. Consent for transaction updates does not automatically cover marketing drips."},
{s:"Companies covered",d:"Identify the brokerage (LPT Realty) and any other company that will contact the consumer, such as an affiliated lender or the mortgage brokerage. Each company that will market should be named; the MLO's company must be listed separately if it will reach out."},
{s:"Opt-out and disclosures",d:"Review that the consumer can revoke consent any time (reply STOP, written notice) and that consent is not a condition of service. Message/data rate language should be on the form (verify on the current form)."},
{s:"Signature and storage",d:"Consumer signs and dates. Store the signed form in the CRM contact record and SkySlope; keep proof of consent for as long as you contact the person. Honor opt-outs immediately and log them."}
],
"LPT-COMMISSIONDISB":[
{s:"Property and escrow data",d:"Enter the property address, escrow company, escrow officer, phone/email and escrow number exactly as they appear on the escrow opening package. Escrow matches the CDA to its file by these; typos cause the demand to be rejected. (confirm with LPT broker/TC)"},
{s:"Side and representation",d:"Indicate whether LPT represents the seller, buyer or both (dual agency). For buyer side, note who pays the compensation (seller via SPBB/RPA, buyer per BRBC, or split)."},
{s:"Gross compensation due to LPT Realty",d:"Enter the gross compensation in both percent and dollars, as stated in the RLA, BRBC, SPBB/CA or RPA. The payee is LPT Realty (brokerage), never the agent. If seller-paid buyer-broker compensation is less than the BRBC amount, show the buyer-paid balance separately."},
{s:"Deductions and separate checks",d:"List outgoing referral fees (payee broker and amount), approved agent credits to the client (attach the Broker Credit Letter) and any transaction fees or invoices escrow should pay from the commission, with payee names so escrow can cut separate checks."},
{s:"Net to LPT and disbursement instruction",d:"Show the net amount escrow should remit to LPT Realty and how (wire/check per LPT instructions). Agent splits inside LPT are handled by LPT after receipt; do not instruct escrow to pay the agent directly."},
{s:"Approval and signatures",d:"Submit through SkySlope for LPT broker/transaction desk review; the CDA is not valid to escrow without LPT's approval signature. Agent signs as preparer."},
{s:"Delivery and settlement statement check",d:"Send the approved CDA to escrow and review the estimated settlement statement before signing to confirm the commission line and any credits match. Mismatched or late CDAs are the most common cause of delayed commission checks."},
{s:"Loan implication",d:"Any agent credit to the buyer must appear on the Closing Disclosure and fit the loan program's IPC/concession limits (VA 4%, FHA 6%, conventional by LTV). Buyer-paid broker fees also appear on the CD; make sure the MLO has the final numbers before the CD is issued."}
],
"LPT-COMMISSIONMODI":[
{s:"Property, escrow and parties",d:"Enter property address, escrow number, escrow officer and the buyer and seller names. Reference the original compensation source (RLA/BRBC/SPBB/RPA) and the previously submitted CDA date. (confirm with LPT broker/TC)"},
{s:"Original compensation",d:"State the original amount in percent and dollars exactly as on the original CDA or agreement, so LPT and escrow can audit the change."},
{s:"Revised compensation",d:"State the revised amount in percent and dollars. If the reduction funds a credit to a client, the credit should ALSO be documented on a Broker Credit Letter and in the contract (ADM/AEA). If a cooperating broker's amount changes, both brokers must agree in writing."},
{s:"Reason for modification",d:"Explain briefly: repair credit, closing-cost credit, appraisal-gap resolution, renegotiated cooperating-broker amount, referral fee added. Say who benefits (buyer, seller, other broker). Reductions that benefit a party must be disclosed to all parties."},
{s:"Approvals and signatures",d:"Route through SkySlope for LPT broker approval; LPT may require the client to sign acknowledging the change when the client's agreement amount is affected (e.g., an RLA commission reduction should also be documented with an MT or ADM). Agent signs."},
{s:"Revised CDA and escrow",d:"Submit a revised CDA with the letter and confirm the settlement statement reflects the new figure. Escrow will not change the commission line based on an email alone."},
{s:"Loan implication",d:"Commission reductions that become buyer credits must be on the CD and count toward VA 4% concession/FHA/conventional IPC caps; the MLO may need to re-disclose. A credit exceeding allowable closing costs cannot be applied and may be lost."}
],
"COOP-PA":[
{s:"Reference block",d:"Enter the RPA date, property (unit) address, cooperative corporation name, buyer and seller names. Note that the buyer is purchasing shares/membership plus a proprietary lease, not real property; the RPA is modified accordingly."},
{s:"Shares, certificate and lease",d:"Enter the number of shares or membership interest being transferred, the stock/membership certificate number if known, and the proprietary/occupancy lease being assigned. Include parking, storage or other appurtenant rights that transfer."},
{s:"Co-op document delivery",d:"Fill the number of days for seller to deliver bylaws, articles, proprietary lease, house rules, financial statements, budget, reserve study, board minutes and any pending assessment/litigation info (verify blanks on the current form). Buyer's review period runs from receipt; calendar it."},
{s:"Board approval contingency",d:"Enter the days for the buyer to submit the board application and the deadline for board approval. This is a separate contingency; removal must be in writing (CR-B). If the board denies, the buyer can cancel and recover the deposit per the form."},
{s:"Fees and transfer taxes",d:"Allocate transfer fees, flip taxes, application and move-in fees and any co-op transfer tax between buyer and seller. Check the co-op's own fee schedule; co-op fees are often larger than HOA transfer fees."},
{s:"Financing and recognition agreement",d:"If financed, note the lender's requirement for a recognition (Aztech-type) agreement from the co-op and that the co-op must be on the lender's approved list. Few conventional programs lend on co-ops; coordinate with the MLO before writing the offer."},
{s:"Signatures and delivery",d:"Buyer and seller sign as part of the offer; deliver to escrow (often a specialized co-op escrow/transfer agent) and upload to SkySlope. Calendar board approval and document review deadlines."}
],
"LPT-DARKHORSEABA":[
{s:"Purpose and provider",d:"This is LPT's affiliated business arrangement disclosure for the provider referred to as Dark Horse (an affiliated settlement service provider; the form pre-prints its identity and LPT's financial interest). Do not edit the provider or ownership text. (confirm with LPT broker/TC which services Dark Horse provides)"},
{s:"Client and property",d:"Enter the client legal name(s), property address (or N/A for buyers without a property) and the date of delivery, which must be at or before the referral."},
{s:"Estimated charges",d:"Leave the charge estimate/range as supplied on the template. If the client asks for actual costs, refer them to the provider's quote."},
{s:"Not-required-to-use statement",d:"The disclosure states the client may shop and is not required to use the affiliate. Never condition services, credits or pricing on using the affiliated provider."},
{s:"Client acknowledgment",d:"Client signs and dates acknowledging receipt (not consent to use). Every client on the agreement signs. Upload to SkySlope; LPT compliance reviews delivery timing."},
{s:"Loan implication",d:"If the affiliate is a mortgage or title provider, the lender's RESPA file may also need the signed disclosure; send a copy to the MLO. Deliver alongside the general LPT AfBA version if LPT requires both. (confirm with LPT broker/TC)"}
],
"DEDA":[
{s:"Reference block",d:"Enter the RPA date, property address and all buyer and seller names exactly as on the contract. The RPA designates email addresses for delivery of notices/documents (verify on the current RPA's electronic delivery/notice paragraph); this amendment changes those designations."},
{s:"New designated addresses",d:"For each affected party and agent, enter the new email address and strike or note the address no longer valid. Spell-check carefully; one typo can defeat delivery of a time-critical NBP, NSP, CR or DCE."},
{s:"Effective date",d:"State when the new address takes effect so deliveries made before that date to the old address remain valid. Without an effective date, parties may argue about notices sent during the changeover."},
{s:"Signatures",d:"All buyers and sellers sign and date (agents sign for agent address changes). Because it amends the contract, one party's signature alone is not enough."},
{s:"Delivery and calendar update",d:"Deliver the signed amendment to the other agent and escrow and update the notice contacts in SkySlope, e-signature platforms and your transaction calendar reminders."},
{s:"Loan implication",d:"Give updated borrower emails to the MLO so LE/CD e-delivery and e-consent go to the correct address; a CD delivered to a dead address can push the 3-business-day waiting period and the closing date."}
],
"LPT-DISCLOSUREREGA":[
{s:"Purpose and timing",d:"LPT's version of the Civil Code 2079.16 agency disclosure (same statutory text as C.A.R. AD). Deliver before the client signs an RLA, BRBC or offer, and to the other party as required. (confirm with LPT broker/TC whether C.A.R. AD is required instead of or in addition to this form for California files)"},
{s:"Client and property",d:"Enter client name(s) and property address, or buyer search/N/A for buyers without a property yet. Date it on delivery."},
{s:"Statutory disclosure text",d:"The client reads the full text describing a seller's agent, buyer's agent and dual agent duties (fiduciary duty to principal, honest and fair dealing to all, disclosure of known material facts). Do not summarize it on the form or alter it; the statute prescribes the text."},
{s:"Agent and brokerage identification",d:"Enter your name, DRE license number, LPT Realty and its broker license number and the responsible broker/office. Mistake: leaving out the license numbers, which is a frequent compliance kickback."},
{s:"Acknowledgment of receipt and signatures",d:"Client signs and dates the acknowledgment; agent signs. For a sale, the buyer's agent delivers to the seller too (via the listing agent) and the listing agent to the buyer, per statute. Upload to SkySlope before the representation agreement is signed."},
{s:"Pairing with other forms",d:"Follow LPT's compliance checklist: the C.A.R. AD plus PRBS (possible representation of more than one buyer or seller) are typically expected in California files. Confirm agency elections are then confirmed in the RLA/BRBC/RPA."}
],
"DLT":[
{s:"Declarant identification",d:"Enter the declarant's full name, DRE license number, license type (salesperson/broker) and status, and the property address/escrow number. If the licensee is a principal (buying or selling for own account), state that here."},
{s:"Role in the transaction",d:"Check whether the licensee is acting as a principal, as an agent receiving compensation, or both. DRE regulations and the RPA require a licensee who is a principal to disclose license status in the contract; this form supports that disclosure (verify on the current form)."},
{s:"Tax reporting information",d:"Provide the payee's legal name, tax classification and TIN ONLY through escrow's secure portal or the attached secure method, never in email. Escrow uses this to issue 1099 or other tax reporting for compensation paid to a non-traditional payee."},
{s:"Compensation to be reported",d:"State the compensation amount or source escrow will report and the payee (the broker, not the agent personally, unless the broker directs otherwise in writing). LPT pays agents; escrow pays LPT."},
{s:"Signature and delivery",d:"Declarant signs and dates under penalty of perjury language if present (verify on the current form). Deliver to escrow and keep a copy in the LPT broker file."},
{s:"Loan implication",d:"If the buyer is a licensee receiving compensation on their own purchase, the lender treats it as an interested-party credit or income; disclose to the MLO early because it can affect cash to close and the CD."}
],
"DPL":[
{s:"Licensee identification",d:"Enter the licensee's full legal name, DRE license number, license type (salesperson, broker, broker-associate, corporation) and expiration date exactly as shown on the DRE public license lookup."},
{s:"Employing / responsible broker",d:"Name the responsible broker or corporate broker (LPT Realty and its license number) under which the licensee works. Compensation can be paid only to a broker; a salesperson's declaration must identify the broker who will receive the funds."},
{s:"Proof attachment",d:"Attach a current DRE license lookup printout showing active status and the employing broker. Escrow may refuse to disburse to an out-of-state or referral broker without proof of licensure in that state (state law differs; verify)."},
{s:"Declaration and signatures",d:"The licensee signs and dates; if escrow requires, the responsible broker also signs. The declaration typically states the license is valid and in good standing (verify on the current form)."},
{s:"Delivery and retention",d:"Deliver to escrow before closing so compensation or referral fees can be disbursed; keep a copy in SkySlope and broker records. No loan implication."}
],
"DSSC":[
{s:"Reference block",d:"Enter the RPA date, the SSA (Short Sale Addendum) date, property address and buyer/seller names. The SSA makes the contract contingent on the seller's lender(s) written consent by a stated deadline; this notice reports the outcome."},
{s:"Election: consent delivered",d:"Check this box when the lender approval letter(s) are received and attach them. Delivery of consent starts the SSA clock: buyer contingency periods and the COE date run from the date this notice (with consent) is delivered (verify on the current form)."},
{s:"Election: failure to deliver",d:"Check this when the lender consent deadline passed without approval. Under the SSA, either party may then cancel, or the parties can extend in writing (ETA). Do not assume the contract is still alive without an extension."},
{s:"Lender terms affecting the deal",d:"Note any approval conditions: reduced broker compensation, limits on seller-paid closing costs or credits, required COE date, cash contribution from seller. These may need an RPA amendment (AEA) and must go to the buyer's MLO."},
{s:"Signatures and delivery",d:"Seller signs and dates; listing agent delivers to buyer's agent and escrow and documents the delivery date. Upload to SkySlope."},
{s:"Loan implication",d:"The buyer's MLO should re-time the rate lock and appraisal from the consent date; lender-imposed closing cost limits or COE deadlines may change the loan structure and require a new LE."}
],
"ECC-B":[
{s:"Buyer and property",d:"Enter the buyer name(s), the property address or a hypothetical price if no property yet, and the date. Use a realistic purchase price so the dollar estimates are meaningful. Reissue when the price or BRBC amount changes."},
{s:"Compensation from the BRBC",d:"Enter the buyer-broker compensation exactly as in the BRBC (percent of price or flat amount). Compute the dollar figure at the entered price. The broker cannot collect more than the BRBC amount from any combination of sources."},
{s:"Scenario: seller/listing broker pays all",d:"Show the amount expected from the seller (via SPBB/RPA) and the buyer's share as zero. Note this is only an estimate until the seller agrees in writing."},
{s:"Scenario: seller pays part",d:"Enter the seller-paid amount and show the buyer-paid balance (BRBC amount minus seller contribution). This is the number that affects cash to close."},
{s:"Scenario: buyer pays all",d:"Show the full BRBC amount as a buyer closing cost. Explain that some loan programs limit financing or crediting of this fee and that it appears on the CD."},
{s:"Acknowledgment",d:"Buyer signs/initials acknowledging the figures are estimates and compensation is negotiable. Agent signs. Attach to the BRBC in SkySlope and update when offers are written."},
{s:"Loan implication",d:"Buyer-paid broker fees increase cash to close and must be disclosed to the MLO before the LE; VA permits the veteran to pay reasonable buyer-broker fees under current guidance but confirm with the MLO; FHA/conventional treat seller-paid broker fees outside IPC limits per current agency guidance (confirm)."}
],
"ECC-S":[
{s:"Seller and property",d:"Enter seller name(s), property address and the estimated sale price (list price or the offer price when reviewing offers). Date it; update whenever an offer changes the numbers."},
{s:"Listing broker compensation",d:"Enter the listing compensation as agreed in the RLA (percent and dollars). Do not describe any rate as standard or customary; the form exists to show negotiability."},
{s:"Compensation to buyer's broker",d:"Enter any amount the seller has authorized in the RLA or has been asked for in an offer/SPBB. Since MLS cannot carry compensation offers, this is the only place the seller sees the number before agreeing."},
{s:"Buyer concessions / credits",d:"Enter seller credits requested toward buyer closing costs and any other concessions (repairs, home warranty). Show them separately from broker compensation so the seller sees total cost of sale."},
{s:"Total estimated cost and net sheet",d:"Total the compensation and concessions and review alongside the ESP (estimated seller proceeds) so the seller understands the net. Mistake: forgetting that a buyer-broker payment reduces net just like a credit."},
{s:"Acknowledgment",d:"Seller signs/initials acknowledging these are estimates and that compensation is negotiable; agent signs. Keep in the listing file and with the offer comparison in SkySlope."},
{s:"Loan implication",d:"Seller-paid buyer-broker compensation is generally excluded from VA/FHA/conventional concession caps under current agency guidance, but seller credits for closing costs are not; confirm with the MLO and make sure both appear correctly on the CD."}
],
"LPT-EXCLUSIVEBUYER":[
{s:"Use and jurisdiction",d:"LPT's brokerage buyer agreement is mainly for states outside California; California buyers normally sign the C.A.R. BRBC (which has California-specific 3-month term and compensation rules). Use this only when LPT instructs. (confirm with LPT broker/TC)"},
{s:"Parties and term",d:"Enter buyer legal name(s), agent name, LPT office/state, and the start and end dates. Keep the term reasonable; some states cap terms or require specific expiration language."},
{s:"Area and property types",d:"Describe the geographic area (counties/cities) and property types covered (residential, land, multi-family). Exclusive means the buyer owes compensation on any covered purchase during the term, even without the agent, so be clear."},
{s:"Compensation",d:"State the amount or rate (percent or flat), that it may be paid by the seller/listing broker or the buyer, and the buyer's obligation for any shortfall. Post-NAR settlement, the amount must be specific and objectively ascertainable, not open-ended, and must be signed before touring."},
{s:"Agency and state disclosures",d:"Attach the state's required agency disclosure, dual agency consent and any brokerage disclosures (LPT Sales Disclosure for that state). Review what services are included."},
{s:"Signatures and filing",d:"Buyer(s) sign before touring any home; agent signs for LPT. Upload to SkySlope for LPT broker review. Any change later uses a modification form, not an email."},
{s:"Loan implication",d:"If the buyer may owe compensation the seller does not pay, tell the MLO so cash to close and the loan program's treatment of buyer-paid broker fees are accounted for in the LE."}
],
"LPT-EXCLUSIVERIGHT":[
{s:"Use and jurisdiction",d:"LPT's brokerage listing agreement is mainly for states outside California; California listings normally use the C.A.R. RLA. Use this only when LPT instructs for that state. (confirm with LPT broker/TC)"},
{s:"Sellers and property",d:"Enter every owner on title with legal names, the property address, legal description/APN and the list price. A listing missing an owner's signature may be unenforceable; check the deed or title report."},
{s:"Term and protection period",d:"Enter start and expiration dates and the protection (tail) period during which a sale to someone introduced during the listing still earns compensation. Follow the state's limits on term and tail language."},
{s:"Compensation and buyer-broker authorization",d:"State the listing compensation (percent/flat) and whether the seller authorizes LPT to offer/pay an amount to buyer brokers (and how much). The MLS cannot display compensation offers; keep the authorization in this agreement."},
{s:"Marketing authorizations",d:"Complete MLS entry, lockbox, signage, photography/video, syndication and open house authorizations; note any seller restrictions. Attach the state-required disclosures (agency, lead paint if pre-1978, property condition)."},
{s:"Signatures and broker approval",d:"All owners sign and date; agent signs for LPT. Upload to SkySlope for LPT broker approval before marketing begins. No direct loan implication."}
],
"LPT-INVOICE":[
{s:"Version selection",d:"Invoice is for LPT transaction/broker fees; External Service Invoice documents third-party services connected to the transaction (e.g., a vendor paid through escrow). (confirm with LPT broker/TC)"},
{s:"Property and escrow",d:"Enter property address, escrow company and escrow number so escrow can place the charge on the correct settlement statement."},
{s:"Billed party and description",d:"Identify who pays (seller, buyer, agent) and describe the fee/service plainly (e.g., Transaction fee per RLA paragraph X, or vendor name and service). Any client-paid fee must already be disclosed and agreed in the RLA/BRBC/contract."},
{s:"Amount and payment instructions",d:"Enter the amount and confirm it matches the agreement or LPT fee schedule. State payee (LPT Realty or the external vendor) and payment method through escrow or direct."},
{s:"Approval and submission",d:"Submit through SkySlope for LPT approval, then send to escrow. Confirm the charge appears on the estimated settlement statement before signing."},
{s:"Loan implication",d:"Broker/transaction fees charged to a buyer appear on the CD and are restricted on some programs (VA non-allowable fees cannot be charged to the veteran); confirm with the MLO before billing a buyer."}
],
"LPT-WIRE":[
{s:"Version selection",d:"Six SkySlope copies: generic Fraud Alert, Wire Fraud Alert, and role-specific versions for Buyers, Sellers, Landlords and Tenants. Use the one matching your client; deliver at the start of representation and again before any funds are wired. (confirm with LPT broker/TC if the C.A.R. WFA is also required)"},
{s:"Client and property",d:"Enter client name(s), property address (or N/A) and the date. Each client signs individually."},
{s:"Warning content",d:"Review the warning: criminals hack/spoof email to send fake wiring instructions; never trust wiring instructions received by email; verify by phone using a known number from the escrow opening package, not from the email; be suspicious of last-minute changes or urgency."},
{s:"Agent commitments",d:"The form typically states the agent will never send wiring instructions by email. Do not forward escrow's instructions; direct the client to call escrow directly."},
{s:"Client acknowledgment",d:"Client signs and dates acknowledging receipt. Upload to SkySlope. Re-deliver or re-brief before the earnest money deposit and before cash-to-close is wired."},
{s:"If fraud is suspected",d:"Call the sending bank immediately to request a recall, notify escrow and the broker, and file at IC3.gov. Speed matters; funds are often unrecoverable after 24-72 hours."},
{s:"Loan implication",d:"Buyers wiring closing funds should verify with escrow by phone; the MLO should remind borrowers at clear-to-close. Lender funding wires are separate but equally targeted."}
],
"FRR-PA":[
{s:"Rule background",d:"FinCEN's Residential Real Estate Rule (31 CFR 1031.320) requires a reporting person (usually the settlement agent/escrow) to report certain non-financed transfers of residential property to legal entities and trusts; it took effect March 1, 2026 (verify current status and any amendments before relying on it)."},
{s:"Reference block",d:"Enter the RPA date, property address, seller and the buyer entity or trust. Identify the person signing for the buyer and their title/capacity (attach RCSD)."},
{s:"Applicability",d:"Check that the transfer is non-financed (all cash, or financed by a lender without an AML program) and the transferee is an entity or trust not exempt under the rule. Financed purchases from a regulated lender are generally excluded; escrow/title makes the final determination."},
{s:"Buyer cooperation obligations",d:"The buyer agrees to deliver beneficial ownership information (names, DOB, addresses, ID numbers of beneficial owners/trustees/settlors, as the rule defines) and the source-of-funds information to the reporting person by the stated deadline so the report can be filed within 30 days after closing (verify)."},
{s:"Seller and escrow obligations",d:"The seller agrees to provide required transferor information. Identify the reporting person (escrow/title) and note that the parties, not the agents, supply data. Agents should not collect SSNs or IDs themselves."},
{s:"Consequences of non-cooperation",d:"Review what happens if the buyer fails to provide information (potential delay or cancellation rights, verify on the current form). Both parties sign; deliver to escrow early so the reporting person can collect data before COE."},
{s:"Loan implication",d:"If the buyer later adds financing from a regulated lender, the transfer may fall outside the rule; tell escrow. Lenders with AML programs do not change the buyer's privacy obligations to escrow."}
],
"HENC":[
{s:"Purpose",d:"Statutory notice of the seller's right to cancel an equity purchase contract (Civil Code 1695.4-1695.5): a buyer (equity purchaser) buying an owner-occupied 1-4 unit residence with a recorded Notice of Default must give the seller a cancellation right. Attach to the NODPA."},
{s:"Parties, property and contract date",d:"Enter the seller (equity seller) and buyer (equity purchaser) names, property address and the date the NODPA was signed. The cancellation period runs from the seller's signing."},
{s:"Cancellation deadline",d:"Compute and enter the deadline: midnight of the fifth business day after the seller signs the contract, or 8:00 a.m. on the day scheduled for the trustee's sale, whichever occurs first. Enter the date and time. Mistake: counting calendar days or ignoring a sale date."},
{s:"Where to send cancellation",d:"Enter the equity purchaser's name and address (physical address) to which the seller mails or delivers the cancellation notice. The notice must be in the statutory format and type size (verify on the current form)."},
{s:"Delivery of two copies",d:"Give the seller two copies of the notice at signing (one to keep, one to send). Document delivery with a signed receipt. Nothing may be recorded or transferred and no funds disbursed until the period ends."},
{s:"Signature on cancellation",d:"The seller signs the cancellation portion only if they are cancelling. Agents should keep the file and recommend attorney involvement; Civil Code 1695 violations carry civil and criminal penalties and equity purchaser representatives must be licensed and bonded (Civ. Code 1695.17)."},
{s:"Loan implication",d:"Lenders scrutinize distressed-seller and non-arm's-length purchases; a financed equity purchase must close after the cancellation period and before the trustee's sale, so coordinate reinstatement/payoff timing with the MLO and trustee."}
],
"LPT-HOLDHARM":[
{s:"Version selection",d:"General Hold Harmless Agreement for any client decision against written advice; Sight Unseen Hold Harmless Agreement for buyers purchasing without personally viewing the property. (confirm with LPT broker/TC when LPT requires it)"},
{s:"Client, property and agreement",d:"Enter client name(s), property address and the RPA or listing date. Date the form before the decision takes effect (e.g., before contingency removal or offer submission)."},
{s:"Description of the decision",d:"Describe the specific decision in plain words (e.g., Buyer elects not to obtain a sewer lateral or roof inspection; Buyer removes all contingencies on day 3; Buyer is purchasing without viewing the property in person) and the advice the agent gave, with the date of that advice."},
{s:"Acknowledgment of risks",d:"The client acknowledges the risks were explained and that they proceed against advice and hold the agent and LPT Realty harmless. For sight-unseen, the client acknowledges photos/video/virtual tours are not a substitute for in-person inspection. Pair with C.A.R. BIW/BIE where applicable."},
{s:"Signatures and supporting evidence",d:"Every client on the transaction signs and dates; agent signs. Keep the emails/texts showing the advice. Upload to SkySlope for LPT broker review."},
{s:"Limits",d:"A hold harmless does not relieve the agent of the duty to give competent advice, conduct a visual inspection (AVID) or disclose known facts; it documents the client's informed choice. Not legal advice; recommend an attorney for contested situations."},
{s:"Loan implication",d:"Sight-unseen or inspection-waived buyers still face lender requirements such as appraisal-required repairs; remind them the appraisal is not an inspection."}
],
"LPT-HOMEOWNERSASSO":[
{s:"Property and seller",d:"Enter property address and seller name(s). Complete at listing intake for any HOA property and update during escrow if dues or assessments change. (confirm with LPT broker/TC)"},
{s:"Associations and management",d:"List each association (master and sub-association), management company name, phone, email and portal/website. Many condos have two or more HOAs; missing one delays escrow's document order."},
{s:"Dues and inclusions",d:"Enter monthly (or annual) dues for each HOA and what they cover (water, trash, insurance, amenities). Verify against the latest HOA statement, not the seller's memory; wrong dues in the MLS can break a buyer's qualification."},
{s:"Special assessments and litigation",d:"Note any special assessments (amount, remaining balance, who pays at close), pending assessments, and known litigation or reserve issues. These feed the HOA disclosure package (Civil Code 4525 documents)."},
{s:"Transfer and document fees",d:"Enter transfer fees, document/demand fees and move-in fees and the customary allocation between buyer and seller. The RPA allocates HOA fees in its cost paragraph; keep this sheet consistent with what the seller agrees to."},
{s:"Restrictions",d:"Note rental restrictions, pet rules, parking, age restrictions or owner-occupancy requirements the seller knows of. These affect buyer suitability and financing (investor buyers, FHA/VA project approval)."},
{s:"Upload and sharing",d:"Upload to SkySlope and share with escrow (to order the HOA package) and the buyer's agent per LPT instructions. Loan implication: MLOs need exact dues for DTI and HOA contacts for condo questionnaires and project review; owner-occupancy ratios and litigation can disqualify a condo project."}
],
"ICA":[
{s:"Parties and effective date",d:"Enter the broker (brokerage entity and designated officer) and the associate-licensee with DRE license numbers and the effective date. DRE Reg. 2726 requires a written agreement between broker and salesperson/broker-associate. LPT agents normally sign LPT's own onboarding agreement; use the C.A.R. ICA only if the LPT broker directs. (confirm with LPT broker/TC)"},
{s:"Independent contractor status and duties",d:"Review the clauses stating the associate is an independent contractor for tax purposes (consistent with Unemployment Ins. Code 650 and the AB 5/B&P 10032 real estate carve-out), is licensed, will comply with law, the Code of Ethics and broker policies, and will submit all documents to the broker."},
{s:"Compensation schedule",d:"Fill in the split (percent to associate/broker), any cap, transaction or desk fees, how referral and team income are split, and when compensation is paid (after broker receives funds). State that compensation is earned only through the broker."},
{s:"Expenses",d:"Allocate MLS/association dues, E&O insurance contributions, marketing, technology and auto expenses. Specify what the broker provides and what the associate pays."},
{s:"Supervision and compliance",d:"Note broker supervision duties (review of documents, trust funds, advertising approval) and the associate's agreement to follow them. Teams and DBAs require separate forms (TEAM, SOFBN)."},
{s:"Termination and post-termination",d:"Set notice periods, treatment of pending transactions and listings after termination (listings belong to the broker), return of files and continuing obligations."},
{s:"Binding arbitration option",d:"Both parties initial the arbitration option only if they agree to arbitrate disputes between broker and associate; read the jury-waiver notice. Do not pre-fill."},
{s:"Signatures and retention",d:"Broker and associate sign and date; broker retains for at least three years per B&P 10148 (verify current retention period). No loan implication."}
],
"LPT-INPUT":[
{s:"Version selection",d:"Five LPT input forms: Residential, Multi Family, Land, Vacant Land and Improvement. Pick the one matching the MLS property class (CRMLS: Residential, Residential Income, Land, etc.). (confirm with LPT broker/TC whether LPT's listing coordinator enters the MLS from this form)"},
{s:"Identification and price",d:"Enter address, APN, county, list price, property subtype, year built, zoning and occupancy from public records or the preliminary title report. Match the RLA list price exactly."},
{s:"Size data and sources",d:"Enter bedrooms, baths, living square footage, lot size and garage spaces and CITE the source (assessor, appraisal, measured). Pair with C.A.R. SFLS so the seller acknowledges the source; inaccurate MLS square footage is a top liability claim."},
{s:"Features and systems",d:"Complete HOA (name, dues, from the HOA Information sheet), parking, pool/spa, view, heating/cooling, utilities, water/sewer, solar (owned/leased), fireplaces, laundry. For Multi Family: unit mix, current rents, leases, expenses and separate metering."},
{s:"Land / Vacant Land / Improvement specifics",d:"For land: zoning, utilities at street, access, topography, soils/percolation reports, entitlements. For Improvement forms: describe improvements, permits and construction details. Do not state buildable or developable without documentation."},
{s:"Showing, access and occupancy",d:"Enter showing instructions, lockbox type/location, tenant occupancy and notice requirements (24-hour notice for tenants), alarm info and pets. Keep contact numbers current."},
{s:"Remarks",d:"Write public and private remarks following CRMLS rules: no compensation offers in the MLS, no fair-housing-sensitive language (no family-friendly, no references to protected classes), no agent contact info in public remarks. Have the seller review for accuracy."},
{s:"Upload and loan implication",d:"Seller reviews/approves, then upload to SkySlope for MLS entry. Accurate square footage, HOA dues and unit count help the MLO and appraiser; MLS data that conflicts with the appraisal or 1003 triggers underwriting conditions."}
],
"ITA":[
{s:"Client and interpreter",d:"Enter the client's name, the interpreter's name, address, phone/email, relationship to the client (friend, relative, professional) and the language interpreted. Avoid using the other party, the other agent or anyone with a stake in the deal as interpreter."},
{s:"Documents and meetings covered",d:"Identify the documents (RLA, BRBC, RPA, disclosures, lease) and meetings the interpreter will assist with. Add later documents by listing them on a new ITA or an addendum."},
{s:"Interpreter's role and limits",d:"Confirm the interpreter is not an agent of the brokerage, is not giving legal, tax or real estate advice, and will interpret accurately. The client acknowledges responsibility for understanding the documents and may obtain a professional translation."},
{s:"Translation notice (Civil Code 1632)",d:"If the agreement was negotiated primarily in Spanish, Chinese, Tagalog, Vietnamese or Korean and a translation is required (e.g., leases over one month; verify which agreements are covered), deliver the translated agreement or the FLTN notice as applicable."},
{s:"Signatures",d:"Client and interpreter sign and date; agent signs acknowledging. Keep the ITA in SkySlope with the interpreted documents."},
{s:"Loan implication",d:"Tell the MLO if the borrower needs an interpreter; lenders have language-access procedures (and Fannie/Freddie language preference questions on the 1003) and the closing/notary signing must be arranged so the borrower understands the loan documents."}
],
"LPT-LCAGENTORDERFO":[
{s:"Agent identification",d:"Enter your full name, LPT agent ID/email and phone exactly as in your LPT profile so the order is credited and billed to the right agent. (confirm with LPT broker/TC what LC stands for in the current form and the services offered)"},
{s:"Property / file reference",d:"Enter the property address, MLS number if assigned and the SkySlope file name so the order can be matched to the transaction and any closing deduction."},
{s:"Items or services ordered",d:"Select or describe each item (e.g., signage, marketing pieces, broker-supplied materials) with quantity, specifications and requested delivery/install dates. Be specific about sign riders, names and phone numbers to print."},
{s:"Payment / billing",d:"Choose card on file, deduct at closing or invoice per the options shown. If deduct at closing, the amount should also appear on your CIF so the commission math reconciles."},
{s:"Signature and submission",d:"Sign and date, upload to the SkySlope file and submit per current LPT instructions; keep a copy to match against the closing deduction. No client or loan implication."}
],
"LDAA":[
{s:"Reference block",d:"Enter the property address, and the title and date of the purchase agreement (RPA and any counter) the addendum attaches to. The RPA's liquidated damages (para. 21B area) and arbitration (para. 22B area) provisions require separate initials from every buyer and seller (verify paragraph numbers on the current RPA)."},
{s:"Additional parties",d:"List each additional buyer and seller by full legal name exactly as on the contract or ASA (e.g., a spouse added later, a co-trustee or an additional entity signer)."},
{s:"Liquidated damages initials",d:"Each additional party initials the liquidated damages provision ONLY if they agree (deposit retention capped at 3% of price for 1-4 unit owner-occupied property under Civil Code 1675). Initials are optional and must never be pre-filled or suggested; a party who does not initial is not bound by that clause."},
{s:"Arbitration initials",d:"Each additional party initials the arbitration of disputes provision only if they agree, after reading the jury-waiver notice. If one side initials and the other does not, there is no arbitration agreement."},
{s:"Signatures and delivery",d:"Each additional party signs and dates; deliver to all parties and escrow with the contract package and upload to SkySlope. Pair with ASA for the signature lines themselves."},
{s:"Loan implication",d:"Escrow and the lender need the complete contract package including every signed addendum; missing initials or signatures delay the lender's contract review and the title company's vesting review."}
],
"LPT-LBP":[
{s:"Version selection",d:"Before 1978 version: full federal lead-based paint disclosure for target housing built before 1978 (42 USC 4852d, 24 CFR 35/40 CFR 745). After 1978 version: documents the build date so the federal rule does not apply. Confirm year built from tax records or the title report; if uncertain, use the pre-1978 form. (confirm with LPT broker/TC if C.A.R. FLD is also required)"},
{s:"Lead warning statement",d:"The pre-1978 form carries the required Lead Warning Statement (different text for sales vs. leases). Do not edit it. Make sure the correct sale or lease version is used."},
{s:"Seller/landlord disclosure",d:"Seller/landlord checks whether they have knowledge of lead-based paint or hazards and lists any reports or records available, then provides those records to the buyer/tenant. Unknown is a valid answer; a false No is not."},
{s:"Pamphlet and buyer/tenant acknowledgment",d:"Deliver the EPA pamphlet Protect Your Family From Lead in Your Home; buyer/tenant initials receipt of the pamphlet, the disclosure and any records."},
{s:"10-day inspection opportunity (sales only)",d:"Buyer initials whether they take the 10-day (or other agreed period) opportunity to conduct a lead risk assessment/inspection or waive it. Coordinate with the RPA investigation contingency period."},
{s:"Agent acknowledgment and signatures",d:"Both agents sign acknowledging their duty to ensure compliance; seller/landlord, buyer/tenant sign and date. Must be completed before the buyer/tenant is obligated. Retain 3 years. Upload to SkySlope."},
{s:"Loan implication",d:"FHA/VA appraisers flag defective paint on pre-1978 homes; the lender may require scraping/repainting and clearance before funding. Share the disclosure and any reports with the MLO."}
],
"LPT-LPTMICHIGANPA":[
{s:"Jurisdiction check",d:"Use only for property located in Michigan, by an agent holding an active Michigan license, when LPT Michigan instructs. Never use for California property; California uses the C.A.R. RPA. (confirm with LPT broker/TC)"},
{s:"Parties, property and price",d:"Enter buyer and seller legal names, property address and legal description/parcel ID, purchase price and earnest money amount and holder (in Michigan typically the broker's trust account or title company per LPT policy)."},
{s:"Financing terms",d:"Complete the financing section (cash, conventional, FHA, VA, MSHDA) with loan amount, interest rate cap, application and commitment deadlines. Confirm terms match the pre-approval; attach FHA/VA amendatory clauses where required."},
{s:"Inspection and other contingencies",d:"Enter inspection period (days), any sale-of-home contingency, well/septic inspection requirements (county point-of-sale rules), and the remedies if inspection issues are not resolved, following Michigan practice."},
{s:"Closing, possession and proration",d:"Enter closing date, possession terms (Michigan often uses post-closing occupancy with a per-day charge and escrow holdback), tax proration method (Michigan uses specific due-date proration conventions) and title insurance/closing fee allocation."},
{s:"Disclosures and attachments",d:"Attach the Michigan Seller's Disclosure Statement, lead paint disclosure if pre-1978, agency disclosure and any LPT Michigan required forms."},
{s:"Signatures and review",d:"All parties sign; follow LPT Michigan broker/transaction coordinator instructions for review and SkySlope filing. Loan implication: the lender needs the fully executed agreement and all addenda; confirm financing terms match the loan approval."}
],
"LPT-SALESDISC":[
{s:"Version selection",d:"47 SkySlope copies: generic Sales Disclosure, LPT Network Realty version, and per-state versions (AL, AZ, CO, DC, FL, GA, IA, ID, IL, KS, LA, MA, MD, MI, MO, MS, NC, NV, PA, RI, SC, TN, TX, VA, WI, WV), many with an 11.30 revision. Use the newest version for the property's state; for California confirm whether generic or LPT Network applies. (confirm with LPT broker/TC)"},
{s:"Client and property",d:"Enter client name(s), property address (or N/A) and your agent name, license number and office as on the listing or buyer agreement. Date on delivery at the start of the relationship."},
{s:"Brokerage model and affiliations",d:"Walk the client through the disclosure of LPT's business model, how LPT and the agent are compensated, and any affiliated business relationships (title, mortgage, etc.). Do not edit the pre-printed disclosure text."},
{s:"State-specific content",d:"State versions contain language required by that state's commission (e.g., brokerage relationship, fees, team disclosures). Using the wrong state version is a common compliance kickback; check the header before sending."},
{s:"Client acknowledgment",d:"Client signs and dates acknowledging receipt; agent signs. Upload to SkySlope before LPT's compliance review deadline (typically within days of the agreement). No loan implication."}
],
"MARSMRN":[
{s:"Applicability",d:"MARS (Regulation O, 16 CFR 1015) covers anyone offering to help a homeowner obtain a loan modification, forbearance or other mortgage relief for consideration. Confirm with your broker whether your activity is covered and whether the real estate licensee exemption (for short sale-only negotiation under certain conditions) applies. Not legal advice."},
{s:"Provider identification",d:"Enter the brokerage name, DRE license number, address and contact details as the provider offering the service, and the homeowner's name and property address."},
{s:"Required disclosures",d:"The notice states: the provider is not associated with the government and the service is not approved by the government or the lender; the lender may not agree to change the loan; the homeowner may stop doing business with the provider at any time and may accept or reject any offer; and (if applicable) that stopping payments could cause loss of the home and damage credit."},
{s:"Timing",d:"Deliver in writing at the first communication with the consumer about relief services, before discussing specific terms. Also deliver the general commercial communication disclosures where advertising is involved (verify on the current form)."},
{s:"Fees",d:"No advance fees: Regulation O and California Civil Code 2944.7 prohibit collecting any fee before the homeowner has a written offer from the lender and accepts it. State this on the notice and in practice."},
{s:"Signature and recordkeeping",d:"Homeowner signs and dates the acknowledgment and receives a copy; keep in the file for the required retention period. Recommend a HUD-approved housing counselor or attorney. No buyer loan implication."}
],
"MARSSN":[
{s:"Provider and homeowner",d:"Enter the listing broker name and license number, seller name(s) and property address at the top. Deliver when taking the short sale listing or agreeing to negotiate with the lender, before contacting the lender."},
{s:"Required MARS statements",d:"The notice states that the broker is not affiliated with the government or the lender, that the lender may not agree to the short sale or to waive deficiency, that the seller may stop using the broker's short sale negotiation at any time, and that the seller may accept or reject any lender offer."},
{s:"Consequences warning",d:"Explain that a short sale can have tax (cancellation of debt income, with possible exclusions) and credit consequences and that deficiency rights vary (Civil Code 580e protects many 1-4 unit sellers); refer the seller to a CPA or attorney. Do not promise approval or debt forgiveness."},
{s:"Fees",d:"No fee may be collected from the seller for negotiation services before the lender approves the short sale; broker compensation comes from sale proceeds as approved by the lender. State any third-party negotiator and their fee separately."},
{s:"Pairing with SSLA",d:"Deliver with the SSLA short sale listing addendum at listing signing; both go in SkySlope with the RLA. Seller signs and dates and receives a copy."},
{s:"Loan implication (buyer side)",d:"Buyer's MLO should plan for long short sale timelines (60-120+ days); rate locks and credit documents may need extensions, and lender approval terms may limit seller-paid closing costs."}
],
"MT":[
{s:"Version selection",d:"MT-1 to MT-3 are seller-side copies (listing agreement changes) and MT-4 to MT-6 buyer-side copies (BRBC changes); use a new copy for each separate modification in the file. C.A.R. also publishes MT-LA and MT-BR specific versions; use those if available (verify on the current form)."},
{s:"Original agreement reference",d:"Identify the agreement by form name (RLA, BRBC, RLAA, lease listing), its date, the property address or buyer search description, and the client name(s). The modification is void if it points to the wrong agreement."},
{s:"Modifications",d:"State each change precisely: new list price, new expiration date, new compensation amount (percent/flat), change in authorized buyer-broker compensation, added/removed exclusions, change in term. Write numbers in both figures and words if the form allows."},
{s:"Effective date and remaining terms",d:"Enter the effective date and confirm that all other terms remain unchanged. For compensation changes after the NAR settlement, the new amount must still be specific and not open-ended."},
{s:"Signatures",d:"Every client who signed the original agreement signs, and the broker (or agent for the broker) signs. An email agreeing to a price reduction is not a modification; MLS price changes without a signed MT violate MLS rules."},
{s:"MLS and escrow updates",d:"Update the MLS within the required time for price/expiration changes (CRMLS rules) and, if a buyer-broker compensation authorization changes while an offer is pending, tell escrow/the cooperating agent. No direct loan implication unless compensation flows to a buyer credit."}
],
"NODPA":[
{s:"Applicability (Civil Code 1695)",d:"Use instead of the RPA when the buyer is an equity purchaser acquiring an owner-occupied 1-4 unit residence that has a recorded Notice of Default and the buyer will not occupy it as a residence. Get legal advice; violations carry civil and criminal penalties. Representatives of the purchaser must be licensed AND bonded (Civ. Code 1695.17; verify)."},
{s:"Parties and property",d:"Enter the equity seller(s) and equity purchaser names, property address and the trustee's sale date if scheduled. Name the purchaser's representative (agent) and their broker."},
{s:"Price and terms",d:"Enter the total consideration, how it is paid (cash, assumption, seller financing), who pays liens/reinstatement, and the closing date. The contract must contain the entire agreement; side agreements are prohibited."},
{s:"Statutory notices and type size",d:"The contract must include the required notices in at least the prescribed type size (e.g., the right-to-cancel notice immediately above the seller's signature; verify current statute). Do not alter the pre-printed statutory text."},
{s:"Right to cancel",d:"Include the seller's right to cancel until midnight of the fifth business day after signing or 8 a.m. on the trustee's sale day, whichever is first, and attach the HENC notice of cancellation (two copies to seller). No deed may be recorded and no funds transferred during the period."},
{s:"Prohibited acts",d:"Review that the purchaser may not take unconscionable advantage, make untrue statements, or have the seller sign a deed or other document before the cancellation period ends (Civ. Code 1695.6). The purchaser cannot resell for two years without satisfying other restrictions in some cases (verify)."},
{s:"Signatures and copies",d:"All parties sign; give the seller a copy of the contract and the cancellation notices at signing; keep proof of delivery. Two SkySlope copies (NODPA and Notice of Default Purchase Agreement) are the same form."},
{s:"Loan implication",d:"Coordinate reinstatement/payoff timing with the foreclosure trustee's sale date; a lender financing the purchase must close after the cancellation period but before the sale, and will scrutinize non-arm's-length and distressed-seller issues."}
],
"OMA":[
{s:"Parties and office",d:"Identify the broker (brokerage entity/designated officer with DRE number), the manager (name, DRE number, salesperson or broker license) and the office/branch location covered. A salesperson may manage a branch only as permitted by DRE regulations (verify B&P 10164/Reg. 2724 requirements)."},
{s:"Management duties",d:"List duties in detail: supervising agents and transactions, reviewing documents within required times, trust account oversight, advertising review, recruiting, training, complaint handling. The designated broker remains responsible even when delegated (Reg. 2725)."},
{s:"Authority and limits",d:"Define what the manager may approve (listings, contracts, commission disbursements) and what requires the broker. Specify reporting lines and written delegation per DRE rules."},
{s:"Compensation and expenses",d:"Set salary, override on office production, profit share or combination; state who bears office expenses and how the manager's own transactions are split."},
{s:"Term and termination",d:"Enter the term, notice periods, termination rights and post-termination obligations (return of files, confidentiality, non-solicitation to the extent lawful)."},
{s:"Signatures and records",d:"Broker and manager sign and date; keep in the brokerage's permanent records. LPT managers use LPT's own agreements unless the LPT broker directs otherwise. No loan implication."}
],
"PA":[
{s:"Estate and property",d:"Enter the estate name (Estate of ___), the probate case number and court if known, the personal representative's name, and the subject property address. Give to the PR at listing and to buyers before offers."},
{s:"Authority under IAEA",d:"Review whether the personal representative has full or limited authority under the Independent Administration of Estates Act (from the Letters). Full authority: sale may close with a Notice of Proposed Action (15-day objection period) and no court hearing; limited authority: court confirmation is required."},
{s:"Court confirmation and overbids",d:"Explain the court confirmation process: hearing date set by the court, open overbidding (first overbid is price plus 10% of the first $10,000 plus 5% of the balance), and that the original buyer may be outbid. Overbidders bring a cashier's check deposit (commonly 10%)."},
{s:"As-is sale and disclosures",d:"Probate sales are generally as-is; the PR is exempt from the TDS and SPQ if they never occupied the property, but must still disclose known material facts; agents still owe visual inspection (AVID). Explain limited contingencies and that timelines may run from confirmation."},
{s:"Compensation",d:"Note that in court-confirmed sales the court approves broker compensation and sets the split if an overbidder wins. Listing side pairs with PLA; buyer side pairs with CCA."},
{s:"Signatures and calendar",d:"Client signs and dates; agent signs; give a copy. Upload to SkySlope and calendar the NOPA objection period or court hearing. Loan implication: court confirmation can delay closing 30-60+ days; buyers should plan for longer rate locks."}
],
"PAC":[
{s:"Parties",d:"Identify the agent (licensee) hiring the assistant, the personal assistant (name, address, licensed or unlicensed with DRE number if licensed) and the supervising broker. Broker approval is required; LPT may require its own form or the TPA instead. (confirm with LPT broker/TC)"},
{s:"Permitted duties",d:"List the assistant's tasks. For unlicensed assistants, exclude licensed activity: no showing property to prospects, no negotiating, no discussing terms or price, no soliciting listings/buyers (DRE unlicensed assistant guidelines). Administrative, marketing and scheduling tasks are allowed."},
{s:"Compensation",d:"Set the pay (hourly, salary or flat); unlicensed assistants cannot be paid a share of commission for licensed activity. Licensed assistants paid commission must be paid through the broker."},
{s:"Employment status",d:"Address employee vs. independent contractor under California's ABC test (AB 5); most assistants controlled by the agent are employees, which triggers payroll, wage/hour and workers' comp obligations. Recommend an employment attorney or payroll service."},
{s:"Confidentiality, systems and termination",d:"Cover client data confidentiality, use of MLS/lockbox (unlicensed assistants cannot have their own MLS access or key in most associations), CRM and e-signature accounts, and termination terms."},
{s:"Signatures and filing",d:"Agent, assistant and broker sign; file with brokerage records. No loan implication."}
],
"LPT-PERSONALPROPER":[
{s:"Header",d:"Enter property address, client name(s) and whether this is for a listing (what seller will include/exclude) or an offer (what buyer requests). (confirm with LPT broker/TC how the sheet is used)"},
{s:"Item list",d:"List each item with description, brand/model, serial if available, and location (e.g., kitchen refrigerator, Samsung stainless; garage freezer). Include window coverings, mounted TVs/brackets, security cameras, potted plants, playsets, EV chargers."},
{s:"Included / excluded / negotiable",d:"Mark each item. Fixtures (attached items) are included by law unless excluded; personal property is excluded unless included. Resolve the mounted TV and bracket question explicitly; it is the most common closing dispute."},
{s:"Leased and financed items",d:"Flag leased solar, water softeners, alarm systems, propane tanks and financed items (PACE/HERO). These must be disclosed, paid off or assumed in escrow, and leased solar requires the solar company's transfer approval; coordinate with escrow and the MLO."},
{s:"Transfer to the contract",d:"Transfer the final list into the RPA items included/excluded paragraph or attach as an ADM; the RPA states included items are transferred without warranty and no value is allocated unless stated. Do not assign a price to personal property without lender approval."},
{s:"Signatures and upload",d:"Client initials and signs; upload to SkySlope. Loan implication: appraisers exclude personal property from value; a large furniture package in the contract can trigger lender review and, if valued, reduce the appraised real property value or require a separate bill of sale outside the loan."}
],
"PLA":[
{s:"Estate and representative",d:"Enter the estate name, probate case number and court, and the personal representative's full legal name and capacity (executor/administrator). Attach the Letters Testamentary or Letters of Administration to the listing file."},
{s:"IAEA authority",d:"Check full or limited authority under the Independent Administration of Estates Act. Full authority allows sale by Notice of Proposed Action (15-day objection window) without a hearing; limited authority requires court confirmation and overbid procedures."},
{s:"Court-set compensation",d:"Acknowledge that in a court-confirmed sale the court approves compensation and sets the split between listing broker and the successful overbidder's broker; the RLA percentage is subject to court approval. In full-authority sales the RLA terms generally apply (verify)."},
{s:"Overbid procedure",d:"Describe the first minimum overbid (price plus 10% of the first $10,000 plus 5% of the excess), that the listing broker may need to market for overbidders, and deposit requirements at the hearing."},
{s:"Disclosures and as-is",d:"Note the PR's TDS/SPQ exemption when the PR did not occupy the property, the continuing duty to disclose known material facts, and that the sale is as-is. Agents still complete the AVID."},
{s:"Signatures and filing",d:"Personal representative signs and dates with the RLA; attach RCSD. Upload to SkySlope with the Letters. No loan implication on the listing side, but advise buyers' agents of the likely timeline."}
],
"POSA":[
{s:"Reference block",d:"Enter the RPA date, property address and buyer/seller names. If part of the offer, list it in the RPA addenda checklist; if agreed later, all parties sign as an amendment."},
{s:"Storage area and access",d:"Describe the exact area (garage, a bedroom, a POD in the driveway) and the buyer's access rights (by appointment, keys not provided). Storage is not occupancy; prohibit overnight stays and living use to avoid creating a tenancy (BEO is for occupancy)."},
{s:"Dates and fee",d:"Enter the start date (and any end date if escrow fails), and any storage fee or deposit. State that the buyer must remove items within a set number of days if escrow does not close."},
{s:"Risk of loss and insurance",d:"Allocate risk: buyer bears loss/damage to stored items and is responsible for damage caused to the property; buyer should carry renter's or inland marine coverage; seller should confirm homeowner's coverage. Buyer may be asked to indemnify seller."},
{s:"Condition and utilities",d:"Note the condition of the storage area before move-in and any utilities the buyer may use. Seller remains responsible for the property until COE."},
{s:"Signatures and delivery",d:"Buyer and seller sign before anything is moved in; deliver to escrow and upload to SkySlope. Loan implication: lenders may question pre-closing possession; tell the MLO, and note the appraiser/final inspection may need access around stored items."}
],
"RA":[
{s:"Licensee identification",d:"Enter the licensee's full name, brokerage, DRE license number and local association/REALTOR membership information. Verify license status on the DRE lookup and membership through NAR's database before relying on it."},
{s:"Arrangement referenced",d:"Identify the related referral fee agreement (RFA) or broker cooperation document by date and client name so the acknowledgment ties to a specific arrangement (verify on the current form)."},
{s:"Code of Ethics acknowledgment",d:"The signer acknowledges REALTOR status and that the arrangement is subject to the Code of Ethics (e.g., Article 16 on cooperation, Article 7 on compensation disclosure). Only REALTOR members can be bound this way."},
{s:"Signature",d:"The receiving licensee signs and dates before any referral fee is paid; the responsible broker signs if required. Attach to the RFA/cooperation agreement."},
{s:"Filing",d:"Keep in SkySlope and brokerage records for the DRE retention period. Referral fees go broker to broker only and never to unlicensed persons. No loan implication; RESPA bars fees for settlement-service referrals."}
],
"RAD":[
{s:"Client and transaction",d:"Identify the referred client by name, the property or search area, the transaction type (sale, purchase, lease) and the referring broker/agent and receiving broker/agent with license numbers."},
{s:"Referral fee",d:"State the fee as a percentage of the gross commission received by the receiving broker (or a flat amount) and when it is paid (at closing through escrow or by the broker after receipt). Match the RFA exactly."},
{s:"Disclosure to the client",d:"Where required, disclose the referral relationship and fee to the client; the receiving REALTOR acknowledges the referral and the fee. Article 6 of the Code of Ethics and state law require disclosure of compensation from third parties in some situations (verify on the current form)."},
{s:"Signatures",d:"Both referring and receiving brokers (or agents for their brokers) sign and date. Attach to the RFA and upload both to SkySlope; LPT uses the CIF Outgoing Referral version at closing."},
{s:"Limits and loan implication",d:"Referral fees are lawful only between licensed brokers; none to unlicensed parties. RESPA Section 8 prohibits fees for referrals of settlement services, so MLOs cannot pay or receive real estate referral fees; keep loan and real estate referrals separate."}
],
"LPT-REFERRALAGREEM":[
{s:"Agents and brokers",d:"Enter the referring and receiving agents' names, brokerages, DRE (or other state) license numbers and full contact information. If both are LPT agents, note the offices/states. (confirm with LPT broker/TC)"},
{s:"Client and transaction",d:"Enter the client's name and contact information, transaction type (buy/sell/lease), location and expected price range. Confirm the client has consented to the referral."},
{s:"Referral fee and term",d:"State the fee as a percentage of the receiving side's gross commission (or flat) and the period during which it applies (e.g., any transaction closed within 12-24 months). Address whether the fee applies to subsequent transactions with the same client."},
{s:"Payment mechanics",d:"Fees are paid broker to broker: escrow pays LPT (or the other broker), which pays the referring broker. Agents never pay each other directly. For outgoing referrals, the LPT CIF Outgoing Referral version is submitted at closing; for incoming, the other broker needs LPT's W-9 and DPL if requested."},
{s:"Signatures and approval",d:"Both agents and both brokers sign; upload to SkySlope for LPT approval before the referral is worked. No loan implication, and no fees for mortgage/settlement-service referrals (RESPA)."}
],
"REOL":[
{s:"Seller entity and asset manager",d:"Enter the lender/servicer seller entity exactly as on title (after the trustee's deed), the asset management company and contact, and the property address. Attach the asset manager's listing instructions to the file."},
{s:"Exempt disclosures",d:"Explain that an REO seller (acquired by foreclosure/deed in lieu) is exempt from the TDS and the NHD statement is still required from a third party (verify), but the exemption does not cover known material facts, and other disclosures (lead paint if pre-1978, water heater/smoke detector statements, Mello-Roos notices) still apply."},
{s:"Continuing duties",d:"The seller must still disclose known material defects; the listing agent must conduct the visual inspection and complete an AVID and disclose what they observe. Recommend the seller obtain inspections (termite, roof) and disclose them."},
{s:"Seller addenda and as-is terms",d:"Note that REO sellers typically require their own addendum that overrides the RPA (per diem penalties, no repairs, limited contingency periods). Advise that the C.A.R. REO (buyer-side advisory) is given to buyers."},
{s:"Occupancy and evictions",d:"Address tenant/former-owner occupancy, cash-for-keys and eviction status; just-cause and Protecting Tenants at Foreclosure Act requirements affect timelines."},
{s:"Signature and filing",d:"The seller's authorized representative/asset manager signs and dates; keep with the RLA and asset manager instructions in SkySlope. No listing-side loan implication; buyer lenders will want the trustee's deed vesting and any seller addendum."}
],
"LPT-SELLERSDISCLOS":[
{s:"Applicability",d:"Confirm with the LPT broker/TC whether this brokerage form is required for the property's state and transaction. In California the TDS and SPQ are the statutory disclosures and this form supplements, never replaces, them. (confirm with LPT broker/TC)"},
{s:"Seller and property",d:"Enter seller name(s), property address, year built, how long the seller has owned/occupied it. Dates help the buyer weigh the answers."},
{s:"Structure, systems and components",d:"Seller personally answers each question on roof, foundation, plumbing, electrical, HVAC, water heater, appliances, pool/spa, solar and any known defects, with Yes/No/Unknown and explanations. Agents never fill in or edit answers."},
{s:"Environmental and site issues",d:"Answer questions on flooding/drainage, soil movement, mold, lead, asbestos, radon, underground tanks, pests, easements, encroachments and neighborhood nuisances. Attach reports referenced."},
{s:"Repairs, permits and insurance claims",d:"List repairs and improvements, whether permits were obtained, insurance claims, HOA disputes, notices of violation and pending litigation. Attach invoices and permits."},
{s:"Seller signature and agent review",d:"Seller signs and dates; listing agent reviews for completeness only. Deliver to the buyer within the contract disclosure period (RPA: 7 days after acceptance unless changed) with the TDS/SPQ."},
{s:"Buyer acknowledgment and upload",d:"Buyer signs receipt (buyer has a right to cancel for a set period after late delivery of statutory disclosures). Upload disclosure and receipt to SkySlope. Loan implication: disclosed roof/foundation/water issues may become FHA/VA appraisal conditions; share early with the MLO."}
],
"LPT-SELLERSNONOCCU":[
{s:"Applicability",d:"For absentee owners, landlords, heirs, trustees and investors who have not lived at the property. Confirm with the LPT broker/TC when LPT requires it; it accompanies, not replaces, the TDS/SPQ or the applicable exemption form. (confirm with LPT broker/TC)"},
{s:"Seller, property and occupancy dates",d:"Enter seller name(s), property address and the dates the seller last occupied the property, or Never. If held as a rental, note tenancy dates and whether the seller visited/inspected."},
{s:"Knowledge the seller does have",d:"Seller describes any knowledge from tenant reports, repair invoices, property manager communications, HOA notices, insurance claims, code violations or inspections. Non-occupancy does not excuse disclosing known facts."},
{s:"Buyer reliance statement",d:"The form advises the buyer to rely on their own inspections because the seller's knowledge is limited; pair with AVID and encourage buyer inspections and contingency use."},
{s:"Signatures and delivery",d:"Seller signs and dates; deliver to the buyer with the TDS/SPQ (or TDS exemption forms where applicable, e.g., trustee or probate); buyer signs acknowledgment. Upload both pages to SkySlope for LPT broker review. No loan implication beyond disclosed defects."}
],
"SIP":[
{s:"Reference block",d:"Enter the RPA date, property address, buyer and seller names. If part of the offer, list it in the RPA addenda checklist. The SIP covers seller possession after COE for 29 days or less; for 30 days or more use the RLAS (Residential Lease After Sale) (verify on the current form)."},
{s:"Possession end date and time",d:"Enter the date and time the seller must vacate (e.g., 5:00 p.m. on a date no more than 29 days after COE). Possession counts from COE; be precise about the hour."},
{s:"Compensation and deposit",d:"Set the per-day amount (or total) the seller pays the buyer, paid through escrow or directly, and a security deposit held by escrow or buyer, with return terms after a move-out inspection. Zero rent is allowed but should be deliberate."},
{s:"Utilities, maintenance and insurance",d:"Assign utilities (seller usually keeps them on until vacating), maintenance, landscaping and repairs during the holdover. Advise both parties to consult their insurers: the buyer's homeowner's policy and the seller's renter's/liability coverage."},
{s:"Condition, walkthrough and holdover",d:"Require the seller to leave the property in the same condition as at COE, provide for a joint inspection at move-out and set holdover damages per day if the seller stays past the date. SIP states it is not a lease; the buyer may still need an unlawful detainer if the seller does not leave."},
{s:"Signatures and delivery",d:"Buyer and seller sign; attach to the RPA, deliver to escrow (rent/deposit may appear on the settlement statement) and upload to SkySlope."},
{s:"Loan implication",d:"Owner-occupancy loans require the buyer to move in within 60 days of closing; lenders may limit rent-backs (some cap at 60 days, some less for FHA/VA) and may require the SIP in the file. Check with the MLO before agreeing to the term."}
],
"SKY-COVER":[
{s:"Transaction identification",d:"Enter the property address, transaction type (sale, lease, referral), listing or buyer side (or both for dual agency) and the SkySlope file name. Follow LPT broker/TC requirements for required fields. (confirm with LPT broker/TC)"},
{s:"Parties and price",d:"Enter buyer and seller legal names (matching the contract), purchase price, acceptance date and the scheduled COE. These feed the commission demand, so they must match the RPA and any counters."},
{s:"Key dates and contingencies",d:"Fill the deposit due date, investigation, appraisal and loan contingency deadlines (default 17/17/17 days from acceptance on the RPA unless changed; verify) and COE. Update after any ETA/AEA."},
{s:"Contacts",d:"List escrow officer, title, lender/MLO, cooperating agent/broker, inspector and TC with phone and email. Include the MLO so the file shows who handles financing."},
{s:"Compensation details",d:"Enter the commission amount/percent, source (RLA/BRBC/SPBB), referral fees, team splits and any transaction fee per LPT instructions. Incomplete sheets delay commission disbursement."},
{s:"Upload and maintenance",d:"Upload to the front of the SkySlope file and update whenever price, dates or parties change. Loan implication: none directly; the loan contingency date here should match what the MLO is working toward."}
],
"SOFBN":[
{s:"Parties and DBA name",d:"Enter the salesperson/broker-associate name and license number, the responsible broker (LPT Realty) and its license number, and the proposed fictitious business name. The DBA must not imply a separate brokerage or mislead the public (DRE Reg. 2731/2773 advertising rules)."},
{s:"County filing and DRE registration",d:"Confirm the FBN statement is filed with the county where the business is located and that the broker has registered the salesperson-owned name with DRE (B&P 10159.5-10159.7) BEFORE use. Attach the county filing and DRE approval."},
{s:"Advertising requirements",d:"All advertising using the name must display the responsible broker's identity (name as licensed and license number) and the salesperson's name and license number in a conspicuous manner. Review LPT's advertising/branding policy; LPT may require specific layouts. (confirm with LPT broker/TC)"},
{s:"Ownership, costs and departure",d:"Address who owns the name and domain/social accounts, who pays filing and renewal costs, and what happens to the name if the salesperson leaves LPT (the DRE registration is tied to the broker; a new broker must re-register)."},
{s:"Supervision and compliance",d:"The broker retains supervision over all activity under the name; the salesperson agrees to comply with all DRE and broker rules. Team names have separate rules (B&P 10159.7); use the TEAM form for those."},
{s:"Signatures and filing",d:"Salesperson and broker sign and date; file a copy with LPT and keep proof of DRE registration in the agent file. No loan implication."}
],
"SSLA":[
{s:"Seller, property and listing reference",d:"Enter seller name(s), property address and the RLA date this addendum modifies. Attach to the RLA at signing when the payoff(s) exceed the expected net proceeds."},
{s:"Lienholders and authorization",d:"Identify every lien (first, second, HELOC, HOA, tax, judgments) with servicer and approximate balance, and confirm the seller authorizes the broker (and any negotiator) to communicate with lienholders; the seller will sign the lender's third-party authorization separately."},
{s:"Lender approval of sale and compensation",d:"State that any sale is subject to lender(s) written approval, that compensation is subject to lender approval and may be reduced, and whether the broker agrees to accept the reduced amount. Explain that approval may require seller contribution or a promissory note."},
{s:"Seller obligations",d:"Seller agrees to provide the lender's required package (hardship letter, financials, tax returns), to not take actions that jeopardize approval, and to disclose any bankruptcy or foreclosure sale date."},
{s:"Advisories",d:"Recommend in writing that the seller consult tax and legal advisors on deficiency (Civil Code 580e for many 1-4 unit loans), cancellation-of-debt income and credit impact. Deliver MARSSN with this addendum; no advance fees."},
{s:"Marketing and offers",d:"Note that offers will be submitted to the lender, that the seller must still accept offers subject to lender approval (using the SSA on the buyer side), and that the listing may continue to be marketed per MLS short sale rules (verify)."},
{s:"Signatures and filing",d:"Every seller signs and dates; upload with the RLA to SkySlope. No listing-side loan implication; buyer lenders will time locks from lender consent (see DSSC)."}
],
"TA":[
{s:"Trust and trustees",d:"Enter the full trust name and date (e.g., The Smith Family Trust dated 1/1/2010), every trustee's name and the property address. Obtain the certification of trust (Probate Code 18100.5) early; title will require it."},
{s:"Trustee authority",d:"Review that the trustee(s) have authority to sell under the trust; if there are co-trustees, confirm whether all must sign. Successor trustees should provide the documents establishing succession (death certificate, acceptance). Attach RCSD to the RLA/RPA."},
{s:"Disclosure exemptions",d:"Explain that a trustee who did not occupy the property within the past year and is not a natural person-type seller may be exempt from the TDS (Civil Code 1102.2) but still must disclose known material facts; the SPQ, NHD, lead paint and other disclosures may still be required (verify). Agents still complete the AVID."},
{s:"Buyer advisory",d:"The buyer is advised that disclosures may be limited and should rely on inspections; deliver a copy to the buyer in the disclosure package for signed acknowledgment."},
{s:"Title and escrow documents",d:"List what escrow/title will need: certification of trust, trustee signatures in capacity, possibly the trust excerpts, and a trustee's deed. Send early to avoid closing delays."},
{s:"Signatures and filing",d:"Trustees sign at listing; buyer acknowledges during escrow. Upload to SkySlope and send trust documents to escrow/title. Loan implication: the buyer's loan docs and title policy reference the vesting; if the buyer is also taking title in a trust, the lender needs its own trust review."}
],
"TCS":[
{s:"Property and parties",d:"Enter the property address, buyer and seller legal names, side represented, purchase price and acceptance date exactly as on the RPA/final counter. Complete at acceptance or when submitting for compliance review."},
{s:"Contacts",d:"List escrow (officer, number), title, lender/MLO, home inspector, termite company, HOA/management, cooperating agent and TC with phones and emails."},
{s:"Key dates",d:"Calendar deposit due (3 business days default), seller disclosures due (7 days), investigation/appraisal/loan contingencies (17 days default unless changed), final walkthrough (5 days before COE) and COE (verify defaults on the current RPA). Update on every ETA/AEA."},
{s:"Compensation",d:"Note commission/compensation per the RLA/BRBC/SPBB, referral fees and any credits so the broker can audit against the CDA."},
{s:"Upload and maintenance",d:"Upload to SkySlope; update when dates change so the file and escrow match. Loan implication: include the loan officer's contact and loan contingency date so the team tracks lender deadlines (appraisal ordered, CTC)."}
],
"TEAM":[
{s:"Team identity and members",d:"Enter the team name, team leader and each member's name and DRE license number. Team names must comply with B&P 10159.7 (include team or similar, not imply a separate brokerage) and LPT's team policy; the responsible broker must be identified in all advertising. (confirm with LPT broker/TC)"},
{s:"Roles and lead distribution",d:"Define each member's role (buyer specialist, listing agent, TC, ISA), how leads are sourced and distributed, and lead ownership rules. Clear rules prevent disputes when a lead closes months later."},
{s:"Compensation splits",d:"Set the split by transaction type (team lead, member-generated, referral, listing vs. buyer side) and note that all compensation flows through the broker to the team leader/members per the broker's commission schedule."},
{s:"Expenses and tools",d:"Allocate marketing, CRM, signage, assistant and lead-generation costs; state what the team provides and what members pay."},
{s:"Client relationships, departures and confidentiality",d:"State who owns client relationships (ultimately the broker), how pending deals and databases are handled on departure (pair with TMEA), and confidentiality of team leads/data."},
{s:"Broker supervision and signatures",d:"The supervising broker approves the team and advertising; all members, the leader and broker sign and file with the brokerage. No loan implication."}
],
"TMEA":[
{s:"Parties and effective date",d:"Enter the team name, team leader, departing member names and the effective departure date. Note whether the member is leaving the team only or also LPT Realty."},
{s:"Pending transactions and listings",d:"List every pending escrow, active listing and buyer agreement with the agreed split after departure and who continues to service the client. Listings and buyer agreements belong to the broker; transfers to another brokerage need LPT broker approval (LPT Authorization to Transfer and Release forms)."},
{s:"Client files, leads and marketing",d:"Address return of client files and databases, CRM access, team phone numbers, websites, social accounts and signage, and the member's continuing confidentiality obligations. Note that the member keeps their own personal contacts per the agreement."},
{s:"Compensation on pending deals",d:"State the split percentages or dollar amounts for each pending deal and when they are paid; LPT pays through its commission process, so submit updated CIFs for those files."},
{s:"Notices and signatures",d:"Confirm required notices to clients and MLS changes; team leader, departing member and broker sign and date; file with the brokerage. No loan implication."}
],
"TOA":[
{s:"Form being supplemented",d:"Identify the form by name and date (e.g., RPA dated ___, SPQ, counter offer) and the property address. Reference the specific paragraph number whose text overflows (e.g., RPA paragraph 3L additional terms; SPQ item 11 explanation)."},
{s:"Overflow text",d:"Write the continuation text clearly, starting with the paragraph number so readers can match it to the main form. Use the same terms and defined words as the main form. Do not introduce new topics that belong in a separate addendum."},
{s:"Page numbering",d:"If text spans pages, number them (page 1 of 2) and keep the form reference on each page. Unsigned or unnumbered overflow pages are easy to lose and may not be enforceable."},
{s:"Signatures",d:"Every party who signed the main form signs and dates the TOA so it is clearly incorporated. For disclosures (TDS/SPQ) the seller signs and the buyer acknowledges."},
{s:"Attachment and delivery",d:"Attach to the main form and upload together to SkySlope and send to escrow. Loan implication: overflow terms that affect price, credits, repairs or occupancy must go to the MLO."}
],
"TOPA":[
{s:"Reference block",d:"Enter the RPA date, property address and buyer/seller names. Attach to the offer when any unit is tenant-occupied. List each unit, tenant names, lease type (fixed/month-to-month), rent and deposit (an estoppel certificate from each tenant should be requested; verify on the current form)."},
{s:"Delivery vacant or occupied",d:"Check whether the property is delivered vacant (seller to terminate tenancies lawfully before COE) or with tenants in place (buyer takes subject to leases). Do not promise vacancy unless the seller can lawfully terminate."},
{s:"Rent control and just-cause status",d:"Identify whether the property is subject to AB 1482 (Civil Code 1946.2/1947.12) or local rent control/just-cause ordinances; a sale is not just cause for eviction. Owner move-in evictions have notice and relocation payment requirements; recommend a landlord-tenant attorney."},
{s:"Notices and timelines",d:"Specify who serves any notices, the required notice periods (30/60/90 days depending on tenancy length and program) and relocation assistance owed under AB 1482 or local law."},
{s:"Deposits, leases and prorations",d:"Address transfer of security deposits (credited to buyer through escrow), assignment of leases, rent proration at COE and delivery of tenant estoppels and rental history. Buyer should review leases during the investigation period."},
{s:"Access and showings",d:"Provide for tenant notice before inspections/appraisal (24 hours written notice under Civil Code 1954) and buyer's access for the final walkthrough."},
{s:"Signatures and loan implication",d:"Buyer and seller sign; attach to the RPA and deliver to escrow and the MLO. Owner-occupied financing (VA/FHA/primary conventional) requires move-in within 60 days, so occupancy must be realistic; lenders may require leases and estoppels for rental income and 2-4 unit loans."}
],
"TPA":[
{s:"Parties and license status",d:"Enter the broker (LPT Realty and its license number), the associate-licensee and the assistant, stating whether the assistant holds a DRE license (with number). Sign before the assistant begins work; LPT may require its own form. (confirm with LPT broker/TC)"},
{s:"Duties and licensed activity",d:"Describe the assistant's duties; for unlicensed assistants, list prohibited licensed activities (showing to prospects, negotiating, discussing terms, soliciting) per DRE guidelines. Licensed assistants may perform licensed activity only under the broker."},
{s:"Compensation",d:"State who pays the assistant (agent or broker) and how; unlicensed assistants cannot receive per-transaction commission for licensed activity. Licensed assistants paid commission must be paid through the broker."},
{s:"Supervision, systems and confidentiality",d:"Set broker supervision, access to MLS/lockbox/CRM/e-signature under proper credentials (no sharing of licensed access), confidentiality of client data and compliance with advertising rules."},
{s:"Employment status and liability",d:"Address employee vs. contractor classification under AB 5 and who carries workers' comp and payroll obligations; recommend employment counsel. Allocate liability for the assistant's acts between agent and broker."},
{s:"Termination and signatures",d:"Set termination terms and return of property/data. Broker, associate-licensee and assistant sign and date; file with the brokerage. No loan implication."}
],
"LPT-W9":[
{s:"Line 1-2: name and business name",d:"Enter the legal name exactly as on the payee's tax return (individual name, or the entity name if an S corp/LLC taxed as such) and any DBA/disregarded entity name on line 2. Name/TIN mismatch triggers IRS B-notices and backup withholding."},
{s:"Line 3: federal tax classification",d:"Check individual/sole proprietor or single-member LLC, C corp, S corp, partnership, trust/estate, or LLC with its tax election letter (C, S or P). A single-member LLC taxed as disregarded uses the owner's name on line 1 and SSN or the owner's EIN. Agents with a licensed corporation use the corporation's EIN (DRE corporate license required to be paid as a corporation)."},
{s:"Line 4: exemptions",d:"Usually blank for individuals; corporations may enter an exempt payee code. FATCA codes do not apply to domestic payees."},
{s:"Address",d:"Enter the mailing address where the 1099-NEC should be sent; update LPT if it changes before year end."},
{s:"Part I: TIN",d:"Enter the SSN (individuals/sole proprietors) or EIN (entities). Submit only through LPT's secure upload process; never email an unencrypted W-9. (confirm with LPT broker/TC for the upload channel)"},
{s:"Part II: certification and signature",d:"Sign and date certifying the TIN is correct, you are not subject to backup withholding and you are a U.S. person. E-signature is acceptable if LPT's system supports it. Required before LPT pays commission, referral fees or vendors. No loan implication."}
]
});
